// 5. Offensive Boat Futures Rebate (#1007):
function futureInterestRebate(g, me, sendTroops, ticks, baseRatePer10) {
  const L = Math.max(1, g.terr[me]), cap = 100 * L, B0 = g.bal[me];
  if (B0 <= cap || ticks <= 0) return 0;
  const fee = iV(32 * B0, 1024);
  const steps = Math.min(30, Math.floor(ticks / 10));
  let bHold = B0, bSend = Math.max(0, B0 - fee - sendTroops);
  const stepGrow = (b) => {
    const f = b > cap ? Math.max(0, 3 - (2 * b) / cap) : 1;
    return Math.min(1.5 * cap, b + b * baseRatePer10 * f);
  };
  for (let k = 0; k < steps; k++) {
    bHold = stepGrow(bHold);
    bSend = stepGrow(bSend);
  }
  const extraInterest = (bSend - (B0 - fee - sendTroops)) - (bHold - B0);
  return Math.max(0, extraInterest);
}

// v24: 4-Combo Engine-Exploit Land + Sea Strategy (by c58)
//
// Core 4 Combos over v23 (0135a3e8):
// 1. Independent Stepping-Stone Island Line (`frogHopStep`):
//    - Small islands (`1-12` px, smaller is strictly better) conquered 100% into `coast[me]` (`needArrive = 2 * isle.size + 8`
//      or full bot-island handoff) so `refreshBorder` promotes all island pixels into `coast[me]`.
//    - Strictly gated to low-fee moments (`maxAbsCost <= 550` or trapped `<= 1500`) or `t + 1` post-land-spend dip in `LiveGame`.
// 2. Multi-Bridgehead Coastal Widening -> 2-Tick `P_BORDER` Wait -> Main Land Assault + Re-Ignite (`reigniteNewBorders`):
//    - Uses minimal `atkFresh = 1` boats (`troopsFor(3, d)`), waits 2 ticks after landing until beachhead pixels turn into
//      `P_BORDER` (widening contact surface area 3x and setting `schedWait = 2`), then fires `g.attack`!
// 3. Exact 1-Ring `attack(0)` Probing (`zeroPulseMode`):
//    - For non-kill probing pulses where `1.20 * need > pulseFrac * B` and `counter === 0`, uses `g.attack(0, q)` so
//      `atkFresh = 1` draws the exact 1st-ring cost from home `bal[me]` tax-free with 0 leftover troops burning on ring 2!
// 4. 1:2 Home Defense Absorption + Wave-Zero Aggressor Counter-Push.


