// v28: first frame of an error stack, for the log.
function firstFrame(e) {
  const s = String((e && e.stack) || "").split("\n");
  return (s[1] || "").trim().slice(0, 160);
}

export class Policy extends V17 {
  constructor(params = {}, me = 0) {
    super({ ...PARAMS, ...params }, me);
    // v28 state (see the v28 sections at the end of the class)
    this.v28n = {}; // trigger counters by name (read by the self-test harness)
    this.v28Faults = {}; // P8: exceptions caught, by step
    this.v28Any = false;
    for (const k of ["enableInflightLedger", "enableSpawnClosedLoop", "enableAiFloorCap", "enableCoordinatedStrike", "enableSmartOverCap", "enableQuotaExactDonate", "enableSeaPrecision", "enableCollapseGuard"]) {
      if (this.p[k] > 0) this.v28Any = true;
    }
    this.peakSeen = 0;
    this.peakT = -1;
    this.lgOn = false;
    this.lgLastKind = null;
    this.lgSampleT = -1e9;
    this.lgTerrOld = 0;
    this.lgTerrNew = 0;
    this.led = []; // P1: commands that have left and not landed, oldest first
    this.ledSeq = 0;
    this.ledSent = []; // ticks of the last commands that left (for the per-three-rounds cap)
    this.ledLastCmdT = -1;
    this.ledPrev = null; // last tick's { t, bal, boats }
    this.ledAtkSeen = new Map(); // target -> our troops on it at the last tick (targets with a command in flight)
    this.ledStall = false;
    this.ledRound = -1;
    this.ledClockT = -1;
    this.ledClockMs = 0;
    this.ledClockStallUntil = -1;
    this.ledBurstTicks = 0;
    this.ledCarryT = -1;
    this.ledCarryN = 0;
    this.ledLandedT = -1; // issue tick of the latest command seen landing
    this.ledSlots = null; // our attacks at the last tick: target -> troops (kept while something is in flight)
    this.nfsTrunc = 0;
    this.nfsByProbe = false;
    this.vKeepNext = null;
    this.buyQuality = false;
    this.p3Old = new Map(); // P3: target -> { t, keep } the floor without the P3 relaxation, this tick
    this.donQuota = 0; // P6: cumulative transfer quota mirror (100 * L per 300 ticks)
    this.donEpoch = 0; // P6: Math.floor(g.t / 300) last credited
    this.boxedSinceT = -1; // P7: tick from which nb.length === 0 && neutral === 0 held continuously
    this.hitTo = new Map();
    this.hitFrom = new Map();
    this.lastLandSpendTick = -999;
    this.shadowQuota = 0;
    this.lastQuotaTick = -1;
    this.isNoFullSend = Boolean(this.p.noFullSend);
    this.pendingQuotaCheck = null;
    this.flState = null;
    this.lastFlashLoan = -999;
    this.flStats = { runs: 0, printed: 0, targets: 0 };
    this.seaState = {
      gate: this, // v28: the module-level sea functions send their commands through this Policy (see gateOf)
      sentBoats: new Map(),
      pendingHandoffs: new Map(),
      widenCount: new Map(),
      widenLandings: new Map(),
      lastActiveCnt: new Map(),
      bankBoats: new Map(),
      lastFrogHop: -999,
      lastWiden: -999,
      stats: {
        froghop: { boats: 0, fee: 0, troops: 0 },
        door_harvest: { boats: 0, fee: 0, troops: 0 },
        widen: { boats: 0, fee: 0, troops: 0 },
      },
    };
  }

  updateShadowQuota(g) {
    const me = this.me, B = g.bal[me], L = Math.max(1, g.terr[me]);
    if (!this.isNoFullSend && Object.prototype.hasOwnProperty.call(g, "noFullSend") && g.noFullSend) {
      this.isNoFullSend = true;
    }
    if (this.lastQuotaTick < 0) {
      this.shadowQuota = g.t > 50 ? Math.max(iV(B, 4), 2048) : 0;
      this.lastQuotaTick = g.t;
    }
    const dt = Math.max(0, g.t - this.lastQuotaTick);
    const target = Math.max(iV(B, 4), 2048);
    if (dt > 0) {
      const cap = Math.min(100 * L, 1e9);
      let r = this.baseRate(g) * 1e4;
      if (B > cap) r -= (2 * r * (B - cap)) / cap;
      const lN = Math.max(Math.min(Math.round(r), 700), 100);
      this.shadowQuota = Math.min(target, this.shadowQuota + dt * iV(lN * target, 1e4));
      this.lastQuotaTick = g.t;
    } else if (this.shadowQuota > target) {
      this.shadowQuota = target;
    }
    if (this.pendingQuotaCheck && g.t >= this.pendingQuotaCheck.t) {
      const pc = this.pendingQuotaCheck;
      if (g.t > pc.t + 6) {
        this.pendingQuotaCheck = null;
      } else if (B < pc.bal0 - pc.fee) {
        const actualSent = Math.max(0, pc.bal0 - B - pc.fee);
        if (pc.want >= 1.12 * actualSent && actualSent < pc.bal0 - pc.fee - 50) {
          this.isNoFullSend = true;
          this.shadowQuota = 0;
        } else {
          this.shadowQuota = Math.max(0, this.shadowQuota - actualSent);
        }
        this.pendingQuotaCheck = null;
      }
    }
  }

  send(g, target, troops, budgetHint = troops) {
    const P = this.p, me = this.me;
    const balBefore = g.bal[me];
    const fee0 = iV(12 * balBefore, 1024);

    // Exploit #3963 (`z4.aSo` 25% No-Full-Sending quota guard & `attack(0)` bypass):
    if (P.quotaGuardMode > 0 && this.isNoFullSend && troops > 2 && this.shadowQuota < Math.min(0.55 * troops, 0.06 * balBefore)) {
      if (
        target !== NEUTRAL &&
        target >= 0 &&
        this.person(g, target) &&
        !g.hasAttack(me, target) &&
        g.attackTroopsOn(target, me) === 0
      ) {
        const cntQ = Math.max(1, this.cnt[target] ?? 1);
        const ring1Def = iV(cntQ * g.bal[target], 1 + iV(10 * g.terr[target], 16));
        const ring1Cost = cntQ * 2 + 2 * ring1Def + 1;
        if (cntQ >= 16 && ring1Cost >= 2.5 * fee0 && ring1Cost <= troops * 1.25) {
          troops = 1; // Use `g.attack(0)` so `atkFresh = 1` draws ring 1 via `aFo` bypassing `aSo`!
        } else {
          return false; // Hold fire during `aSo` cooldown instead of paying 1.17% fee for a clamped trickle!
        }
      } else if (target !== NEUTRAL) {
        return false;
      }
    }

    const ok = super.send(g, target, troops);
    if (ok) {
      // v28/P3: a send the floors of Vc had no room for
      const p3 = this.p3Old.get(target);
      if (p3 && p3.t === g.t && troops > balBefore - p3.keep - (g.t >= P.dpEnd ? fee0 : 0)) {
        this.vCount("p3_relax_send");
        this.vLog("P3", g, `relax q=${target} x=${Math.round(troops)} bal=${balBefore} floorVc=${Math.round(p3.keep)} balQ=${g.bal[target]} terrQ=${g.terr[target]}`);
      }
      if (!g.online) {
        const actualSent = Math.max(0, balBefore - g.bal[me] - fee0);
        if (troops >= 1.12 * actualSent && actualSent < balBefore - fee0 - 50) {
          this.isNoFullSend = true;
          this.shadowQuota = 0;
        } else {
          this.shadowQuota = Math.max(0, this.shadowQuota - actualSent);
        }
      } else if (!(P.enableInflightLedger > 0 && P.p1NoFullFix > 0)) {
        // (v28/P1: with the ledger on, the truncation probe runs on ledger landings, see ledgerObserve)
        this.pendingQuotaCheck = { t: g.t + 1, bal0: balBefore, fee: fee0, want: troops };
      }
      if (g.bal[me] <= 0.75 * balBefore) {
        this.lastLandSpendTick = g.t;
      }
      if (target !== NEUTRAL && target >= 0 && this.person(g, target)) {
        this.hitTo.set(target, g.t);
        const cq = this.cnt[target] ?? 0;
        const stepsQ = (0.75 * g.terr[target]) / Math.max(1, cq);
        if (
          P.seaCore > 0 &&
          g.terr[target] >= 5000 &&
          (cq < 28 || (P.widenStepsMin > 0 && cq < 120 && stepsQ >= P.widenStepsMin)) &&
          (this.seaState.widenCount.get(target) ?? 0) < 2
        ) {
          const B = g.bal[me], fee = iV(32 * B, 1024);
          if (B >= 1000 && fee <= 0.20 * budgetHint && g.boatCount[me] < 5) {
            const spots = findCoastalBridgeheads(g, me, this.seaState, target, {
              maxWaterDist: 25,
              maxSpots: Math.min(2, 5 - g.boatCount[me]),
              minSpacing: 22,
            });
            if (spots.length > 0) {
              const dq = g.bal[target] / Math.max(1, g.terr[target]);
              const counterZero = P.atkFreshBoats > 0 && g.attackTroopsOn(target, me) === 0;
              const needOnShore = counterZero ? 6 : Math.max(30, Math.ceil(2 * (2 + 3.2 * dq) + 15));
              for (const sp of spots) {
                const curB = g.bal[me];
                if (curB < 500 || iV(32 * curB, 1024) > 0.16 * budgetHint) break;
                const sendTr = Math.max(60, Math.ceil(needOnShore * Math.exp(P.boatDecay * sp.d)));
                const pct = Math.max(0, Math.min(1023, Math.ceil((sendTr * 1024) / curB) - 1));
                const launched = g.boatTo ? this.xBoatTo(g, pct, sp.landPix, 12, 'sendWiden') : this.xBoat(g, pct, sp.waterPix, sp.dir, 'sendWiden');
                if (launched) {
                  this.seaState.widenLandings ??= new Map();
                  const wl = this.seaState.widenLandings.get(target) ?? [];
                  wl.push(sp.landPix);
                  this.seaState.widenLandings.set(target, wl);
                  this.seaState.widenCount.set(target, (this.seaState.widenCount.get(target) ?? 0) + 1);
                  this.seaState.stats.widen.boats++;
                  this.seaState.stats.widen.fee += iV(32 * curB, 1024);
                  this.boats++;
                }
              }
            }
          }
        }
      }
    }
    return ok;
  }

  isTeammate(g, p) {
    return !!(g.teams && g.teams[this.me] > 0 && g.teams[p] === g.teams[this.me]);
  }

  isProtectedSquadMate(g, p) {
    if (this.isTeammate(g, p) || this.isBossNpl(g, p)) return true;
    const P = this.p;
    if (!(P.enableCollapseGuard > 0 && P.p8Roster > 0)) return false;
    if (this.vShell(g, p)) return false;
    const roster = this.vRoster(g);
    if (!roster || !roster.includes(p)) return false;
    return this.hasWildOutsidersAlive(g);
  }

  hasWildOutsidersAlive(g) {
    const roster = this.vRoster(g);
    for (let p = 0; p < g.humans; p++) {
      if (!g.alive[p] || g.terr[p] < 80 || g.isBot(p) || this.vShell(g, p)) continue;
      if (this.isTeammate(g, p)) continue;
      if (roster ? roster.includes(p) : this.isSquadName(g, p)) continue;
      return true;
    }
    return false;
  }

  isBossNpl(g, p) {
    if (p === this.me || !g.alive[p]) return false;
    const raw = String(g.names?.[p] ?? "").trim();
    const low = raw.toLowerCase();
    if (
      low.includes("mishi") || low.includes("matzz") || low.includes("kiholma") ||
      low.includes("leo_99") || low.includes("racoon") || low.includes("zexos") ||
      low.includes("talon") || low.includes("vortex") || low.includes("kronos") || low.includes("nexus") ||
      low.includes("777") || low.includes("sayo") || low.includes("kaito") ||
      low.includes("riku") || low.includes("_alex") || low.includes("tomo") ||
      low.includes("zero_2") || low.includes("sora") ||
      low.includes("lucas94") || low.includes("dave_w") || low.includes("mark07") ||
      low.includes("kevin_k") || low.includes("ethan21") || low.includes("ryan_m") ||
      low.includes("noah88") || low.includes("leo_tx") || low.includes("alex_k") || low.includes("zero_7")
    ) {
      return false;
    }
    const stripped = raw.replace(/\[[^\]]*\]/g, "").trim().toLowerCase();
    return stripped === "kazerd183" || stripped.includes("kazerd") || low.includes("kazerd183") || stripped === "npl" || stripped.includes("npl") || low === "[npl]npl";
  }

  findBossId(g) {
    for (let p = 0; p < g.humans; p++) {
      if (this.isBossNpl(g, p) && (this.isTeammate(g, p) || !g.teams)) return p;
    }
    return -1;
  }

  // v28/P8: a seat is one of ours when it is on our team, has not left the game (a seat that left is
  // run as a bot) and is on the roster of the spawn coordinator for this room; without a roster, the
  // name list of Vc below.
  isOurSquadBot(g, p) {
    const P = this.p;
    if (!(P.enableCollapseGuard > 0 && P.p8Roster > 0)) return this.isSquadName(g, p);
    if (p !== this.me) {
      if (this.vShell(g, p)) return false;
      if (g.teams && g.teams[this.me] > 0 && g.teams[p] !== g.teams[this.me]) return false;
    }
    const roster = this.vRoster(g);
    return roster ? roster.includes(p) : this.isSquadName(g, p);
  }

  isSquadName(g, p) {
    const raw = String(g.names?.[p] ?? "").trim();
    const low = raw.replace(/\[[^\]]*\]/g, "").trim().toLowerCase();
    return (
      low === "mishi" || low === "matzz" || low === "kiholma" || low === "leo_99" || low === "racoon" ||
      low === "zexos" || low === "talon" || low === "vortex" || low === "kronos" || low === "nexus" ||
      low === "777" || low === "sayo" || low === "kaito" || low === "riku" ||
      low === "_alex" || low === "tomo" || low === "zero_2" || low === "sora" ||
      low === "lucas94" || low === "dave_w" || low === "mark07" || low === "kevin_k" ||
      low === "ethan21" || low === "ryan_m" || low === "noah88" || low === "leo_tx" ||
      (!g.isBot || !g.isBot(p)) && (low === "alex_k" || low === "zero_7" || low === "kaito9" || low === "riku_x" || low === "sora_w" || low === "zexos1" || low === "talon5")
    );
  }

  // DISTRIBUTED BACKEND-COORDINATED TEAM SPAWNING:
  // 2) In autonomous 5-brother matches (without Boss), uses the original 80%-winrate distributed Voronoi
  //    spawnVsPeople(gClean) with TWO critical fixes:
  //      - Fixed slot = window.__tsbSquadSlot (0..4) so all 5 workers have deterministic, non-overlapping slots
  //        even when joining on different frames;
  //        never leaks a squadmate's own coordinates!
  chooseSpawn(g, final = true) {
    const me = this.me;
    const W = g.W, H = g.H;
    const mySquadIdx = typeof window !== "undefined" && Number.isInteger(window.__tsbSquadSlot) ? window.__tsbSquadSlot : 0;
    const squadIds = [];
    for (let p = 0; p < g.humans; p++) {
      if (p === me || (this.isOurSquadBot(g, p) && !this.isBossNpl(g, p))) {
        squadIds.push(p);
      }
    }
    const rankIdx = Math.max(0, squadIds.indexOf(me));
    const squadCount = Math.max(10, squadIds.length);
    const slot = mySquadIdx % 10;

    // spawn on the #1 Main Continent with geodesic Voronoi spacing and NEVER stack on the same point!
    const bossId = this.findBossId(g);
    if (true) {
      const mapKey = `${W}x${H}_${g.land}_${g.humans}`;
      const nowMs = typeof performance !== "undefined" ? performance.now() : Date.now();
      if (typeof window !== "undefined" && window.__hlSpawnReq && (!this._lastSpawnReqAt || nowMs - this._lastSpawnReqAt > 260)) {
        this._lastSpawnReqAt = nowMs;
        const humans = [];
        for (let p = 0; p < g.humans; p++) {
          const terr = g.terr[p] | 0;
          humans.push({
            id: p,
            name: String(g.names?.[p] ?? ""),
            team: g.teams ? (g.teams[p] | 0) : 0,
            terr,
            x: terr > 0 ? ((g.x0[p] + g.x1[p]) >> 1) : -1,
            y: terr > 0 ? ((g.y0[p] + g.y1[p]) >> 1) : -1,
          });
        }
        const needMap = window.__lastSentSpawnMapKey !== mapKey;
        if (needMap) window.__lastSentSpawnMapKey = mapKey;
        const mapType = needMap ? (g.map?.type || g.px) : undefined;
        const curX = g.terr[me] > 0 ? ((g.x0[me] + g.x1[me]) >> 1) : -1;
        const curY = g.terr[me] > 0 ? ((g.y0[me] + g.y1[me]) >> 1) : -1;
        window.__hlSpawnReq({
          matchKey: mapKey, W, H, land: g.land, me, slot, rankIdx, squadCount,
          myTeam: g.teams ? (g.teams[me] | 0) : 0, curX, curY, humans, mapType,
        });
      }
      if (
        typeof window !== "undefined" &&
        window.__tsbAssignedSpawn &&
        Number.isInteger(window.__tsbAssignedSpawn.x) &&
        (!window.__tsbAssignedSpawn.mapW || (window.__tsbAssignedSpawn.mapW === W && window.__tsbAssignedSpawn.mapH === H))
      ) {
        const res = window.__tsbAssignedSpawn;
        if (window.__hlLog && (!this._lastLogSpawn || Math.hypot(res.x - this._lastLogSpawn.x, res.y - this._lastLogSpawn.y) > 4)) {
          this._lastLogSpawn = { x: res.x, y: res.y };
          window.__hlLog(`[HL-SPAWN-BACKEND] me=${me} slot=${res.slot ?? slot} role=${res.role || "SQUAD"} -> (${res.x},${res.y}) bossDist=${res.bossDist ?? -1} minAllyDist=${res.minAllyDist ?? -1} voronoi=${res.voronoiPixels ?? -1}`);
        }
        return { x: res.x, y: res.y };
      }
    }

    // Autonomous 5-brother distributed Voronoi spawn (original 36b5718 logic with fixed slot 0..4 and clean cache):
    const minSep = Math.max(96, Math.min(175, 0.14 * Math.hypot(W, H)));
    let gClean = g;
    for (const sid of squadIds) {
      if (sid !== me && gClean.terr[sid] > 0) {
        gClean = withoutPlayer(gClean, sid);
      }
    }

    // Throttle expensive spawnVsPeople BFS to at most once every 2200ms during spawnPhase so Worker never lags >3000ms!
    const nowSpawnMs = typeof performance !== "undefined" ? performance.now() : Date.now();
    if (!this._cachedSpawnCands || !this._lastSpawnCalcMs || nowSpawnMs - this._lastSpawnCalcMs > 2200 || this._cachedSpawnW !== W) {
      this._lastSpawnCalcMs = nowSpawnMs;
      this._cachedSpawnW = W;
      let rawCands = this.spawnVsPeople ? this.spawnVsPeople(gClean, 36) : [];
      if (!rawCands || rawCands.length < 12) {
        const more = this.spawnCandidates(gClean, 24) || [];
        rawCands = [...(rawCands || []), ...more];
      }
      this._cachedSpawnCands = rawCands;
    }
    let cands = this._cachedSpawnCands;
    if (cands && cands.length > 0) {
      const comp = this.compSize ? this.compSize(gClean) : null;
      const minMainLand = Math.min(18000, Math.floor(0.18 * Math.max(1, g.land)));
      const chosenSlots = [];
      for (const pos of cands) {
        const x = typeof pos === "object" ? pos.x : (pos % W);
        const y = typeof pos === "object" ? pos.y : Math.floor(pos / W);
        if (comp && comp[y * W + x] > 0 && comp[y * W + x] < minMainLand) continue;
        let tooClose = false;
        for (const prev of chosenSlots) {
          if (Math.hypot(x - prev.x, y - prev.y) < minSep) { tooClose = true; break; }
        }
        if (!tooClose) {
          chosenSlots.push({ x, y });
          if (chosenSlots.length > slot) break;
        }
      }
      if (chosenSlots.length <= slot) {
        const relaxSep = minSep * 0.62;
        for (const pos of cands) {
          const x = typeof pos === "object" ? pos.x : (pos % W);
          const y = typeof pos === "object" ? pos.y : Math.floor(pos / W);
          if (comp && comp[y * W + x] > 0 && comp[y * W + x] < minMainLand) continue;
          if (chosenSlots.every((p) => Math.hypot(x - p.x, y - p.y) >= relaxSep)) {
            chosenSlots.push({ x, y });
            if (chosenSlots.length > slot) break;
          }
        }
      }
      let res = chosenSlots[slot] || cands[slot % cands.length];
      if (!chosenSlots[slot] && chosenSlots.length > 0) {
        const pxArr = gClean.px;
        for (let sIdx = chosenSlots.length; sIdx <= slot; sIdx++) {
          let bestPt = null, bestD = -1;
          for (let y = 18; y < H - 18; y += 16) {
            for (let x = 18; x < W - 18; x += 16) {
              const idx = y * W + x;
              if (pxArr[idx] !== 0) continue;
              if (comp && comp[idx] > 0 && comp[idx] < minMainLand) continue;
              let minD = 999999;
              for (const p of chosenSlots) minD = Math.min(minD, Math.hypot(x - p.x, y - p.y));
              for (let h = 0; h < gClean.humans; h++) {
                if (h !== me && gClean.terr[h] > 0) {
                  const hx = (gClean.x0[h] + gClean.x1[h]) >> 1, hy = (gClean.y0[h] + gClean.y1[h]) >> 1;
                  minD = Math.min(minD, Math.hypot(x - hx, y - hy) * 1.15);
                }
              }
              if (minD > bestD) {
                bestD = minD;
                bestPt = { x, y };
              }
            }
          }
          if (bestPt) chosenSlots.push(bestPt);
        }
        res = chosenSlots[slot] || res;
      }
      res = typeof res === "object" ? res : { x: res % W, y: Math.floor(res / W) };
      if (typeof window !== "undefined" && window.__hlLog && (!this._lastLogSpawn || Math.hypot(res.x - this._lastLogSpawn.x, res.y - this._lastLogSpawn.y) > 6)) {
        this._lastLogSpawn = res;
        window.__hlLog(`[HL-SPAWN] me=${me} slot=${slot} (squad=${squadIds.length},rankIdx=${rankIdx}) -> (${res.x},${res.y}) chosenSlots=${chosenSlots.length}/${cands.length} minSep=${Math.round(minSep)}`);
      }
      return res;
    }
    return super.chooseSpawn(g, final);
  }

  otherHumanMedDens(g) {
    const me = this.me, H = g.humans;
    const ds = [];
    for (let p = 0; p < H; p++) {
      if (p !== me && !this.isTeammate(g, p) && g.alive[p] && g.terr[p] >= 100 && !g.isBot(p)) {
        ds.push(g.bal[p] / g.terr[p]);
      }
    }
    if (!ds.length) return null;
    ds.sort((a, b) => a - b);
    return ds[ds.length >> 1];
  }

  livingHumanCount(g) {
    let n = 0;
    for (let p = 0; p < g.humans; p++) {
      if (!this.isTeammate(g, p) && g.alive[p] && g.terr[p] >= 100 && !g.isBot(p)) n++;
    }
    return Math.max(1, n);
  }

  topOtherHuman(g) {
    const me = this.me, H = g.humans;
    let bestP = -1, bestL = 0;
    for (let p = 0; p < H; p++) {
      if (p !== me && !this.isTeammate(g, p) && g.alive[p] && g.terr[p] > bestL && !g.isBot(p)) {
        bestL = g.terr[p];
        bestP = p;
      }
    }
    return bestP;
  }

  // AUTO PEACE VOTE CALL & ACCEPT:
  tryPeaceVote(g) {
    if (this.findBossId(g) < 0) return; // Never initiate or vote peace in autonomous squad mode — always conquer 100% of the map!
    if (typeof window === "undefined" || !window.ax || !window.dictionary || g.t < 1610) return;
    const me = this.me;
    const hz = window[window.dictionary.sbCommands]?.hz;
    if (!hz) return;
    let ourTeamLand = g.terr[me] || 0;
    if (g.teams && g.teams[me] > 0) {
      ourTeamLand = 0;
      for (let p = 0; p < g.players; p++) {
        if (g.alive[p] && g.teams[p] === g.teams[me]) ourTeamLand += g.terr[p];
      }
    }
    let topPlayer = -1, topTerr = -1;
    for (let p = 0; p < g.players; p++) {
      if (g.alive[p] && g.terr[p] > topTerr) {
        topTerr = g.terr[p];
        topPlayer = p;
      }
    }
    const weHoldCrown = topPlayer >= 0 && (topPlayer === me || this.isOurSquadBot(g, topPlayer) || this.isBossNpl(g, topPlayer));
    const weLead = weHoldCrown && (ourTeamLand >= 0.65 * Math.max(1, g.land) || this.isMopUp(g));
    const caller = window.__lastPeaceCaller;
    const callerIsOurs =
      weHoldCrown &&
      Number.isInteger(caller) &&
      caller >= 0 &&
      caller < g.humans &&
      (caller === me || this.isOurSquadBot(g, caller) || this.isBossNpl(g, caller));
    if (window.ax.iL && typeof window.ax.iM === "function" && window.ax.iM(me)) {
      if (callerIsOurs && typeof hz.iN === "function") {
        hz.iN(1);
        if (window.__hlLog && g.t - (this._lastPeaceVoteLog ?? -999) >= 100) {
          this._lastPeaceVoteLog = g.t;
          window.__hlLog(`[HL-PEACE] t=${g.t} voted YES on our squad's peace call by p=${caller}(${g.names?.[caller] || ""}) (teamLand=${(100 * ourTeamLand / Math.max(1, g.land)).toFixed(1)}%)`);
        }
      }
    } else if (!window.ax.iL && weLead && g.t - (this.lastPeaceKeyTick ?? -999) >= 105 && typeof window.ax.iO === "function" && window.ax.iO(me)) {
      this.lastPeaceKeyTick = g.t;
      window.__lastPeaceCaller = me;
      if (typeof hz.iK === "function") {
        hz.iK();
        if (window.__hlLog) window.__hlLog(`[HL-PEACE] t=${g.t} initiated peace vote (teamLand=${(100 * ourTeamLand / Math.max(1, g.land)).toFixed(1)}%)`);
      }
    }
  }

  // BOSS SUPPORT: CASH DONATION FIRST, ~10% LIGHT ASSIST SECOND!
  // "最好的解围是给钱，打人只是附和10个点左右"
  tryEmergencyBossRescue(g) {
    const me = this.me;
    if (!g.teams || !(g.teams[me] > 0) || !g.canAct(me)) return false;
    const bossId = this.findBossId(g);
    if (bossId < 0 || !g.alive[bossId] || g.terr[bossId] < 50) return false;

    const B = g.bal[me], L = Math.max(1, g.terr[me]), dMe = B / L;
    const B_boss = g.bal[bossId], L_boss = Math.max(1, g.terr[bossId]), dBoss = B_boss / L_boss;

    let bossInAtk = 0, bossOutAtk = 0;
    const bossAttackers = [];
    for (const a of g.attackersOf(bossId)) {
      if (a !== me && !this.isTeammate(g, a)) {
        const tr = g.attackTroopsOn(a, bossId);
        bossInAtk += tr;
        if (!g.isBot(a) || tr > 0.08 * B_boss) bossAttackers.push({ q: a, tr, isEnemyAtk: true });
      }
    }
    const sbB = g.slotBase(bossId);
    for (let i = 0; i < g.atkCount[bossId]; i++) {
      const tgt = g.atkTarget[sbB + i];
      if (tgt >= 0 && tgt < g.humans && !g.isBot(tgt) && !this.isTeammate(g, tgt)) {
        const tr = g.atkTroops[sbB + i];
        bossOutAtk += tr;
        if (!bossAttackers.some(x => x.q === tgt)) bossAttackers.push({ q: tgt, tr, isEnemyAtk: false });
      }
    }

    if (typeof g.donate === "function" && g.t >= 350) {
      let myHumanInAtk = 0;
      for (const a of g.attackersOf(me)) {
        if (!g.isBot(a) && !this.isTeammate(g, a)) myHumanInAtk += g.attackTroopsOn(a, me);
      }
      const enemyHumanNbs = this.nb.filter((p) => g.alive[p] && this.person(g, p));
      const hasExposedCoast = (g.coast?.[me]?.length ?? 0) > 0;
      // Coastal rear bots MUST keep >= 68*L anti-boat-sneak-attack reserve so their back is never stolen by sea!
      const coastGuardFloor = hasExposedCoast && g.t >= 1100 ? 68 * L : 18 * L;
      const safeFloor = Math.max(coastGuardFloor, enemyHumanNbs.length > 0 ? this.safeAt(g, -1) : 0);
      const isPureInlandSafe = enemyHumanNbs.length === 0 && !hasExposedCoast && myHumanInAtk === 0;
      const isCoastalRearSafe = enemyHumanNbs.length === 0 && hasExposedCoast && myHumanInAtk === 0;
      const isUnderThreat = myHumanInAtk > 0 || B <= 1.10 * safeFloor;

      if (!isUnderThreat) {
        const underEmergencyFire = bossInAtk > 0 && (bossInAtk >= 0.03 * B_boss || dBoss < 95);
        const bossFightingHuman = bossOutAtk > 0 && dBoss < 115;
        const bossNeedsCash = g.t >= 950 && dBoss < 118;
        const boxedIn = this.nb.length === 0 && this.neutral === 0 && dBoss < 142;

        const minKeepDens = isPureInlandSafe ? (underEmergencyFire ? 15 : 22) : isCoastalRearSafe ? (underEmergencyFire ? 52 : 72) : (underEmergencyFire ? 58 : 78);
        const canAfford = dMe >= minKeepDens && B > 1.10 * safeFloor;

        const cooldown = isPureInlandSafe ? (underEmergencyFire ? 10 : 18) : (underEmergencyFire ? 15 : 25);
        if ((underEmergencyFire || bossFightingHuman || bossNeedsCash || boxedIn) && canAfford && g.t - (this.lastBossDonateTick ?? -999) >= cooldown) {
          const maxSurplus = Math.max(0, B - Math.max(safeFloor, (minKeepDens - 10) * L));
          const maxPct = Math.floor((maxSurplus * 1024) / Math.max(1, B));
          const targetPct = isPureInlandSafe
            ? (underEmergencyFire ? 350 : boxedIn ? 320 : 220)
            : isCoastalRearSafe
              ? (underEmergencyFire ? 220 : 160)
              : (underEmergencyFire ? 150 : 115);
          const pct = Math.min(maxPct, targetPct);
          if (pct >= 55 && this.xDonate(g, pct, bossId, 'bossRescue')) {
            this.lastDonateTick = g.t;
            this.lastBossDonateTick = g.t;
            this.cmds++;
            if (typeof window !== "undefined" && window.__hlLog) {
              window.__hlLog(`[HL-DONATE] t=${g.t} emergency boss donate pct=${pct}/1024 -> boss=${bossId}(${g.names?.[bossId] || "npl"}) myBal=${B} dMe=${Math.round(dMe)} dBoss=${Math.round(dBoss)}`);
            }
            return true;
          }
        }
      }
    }

    // 2. SECONDARY: Light ~10%B (pct=102/1024) assist poke ONLY if we share a land border and have healthy density!
    if (bossAttackers.length > 0 && B >= 25000 && dMe >= 86 && g.t - (this.lastAssistPokeTick ?? -999) >= 36) {
      bossAttackers.sort((a, b) => (b.isEnemyAtk - a.isEnemyAtk) || (b.tr - a.tr));
      for (const { q } of bossAttackers) {
        if (!g.alive[q] || g.terr[q] < 100) continue;
        if ((this.cnt[q] ?? 0) > 0 && !g.hasAttack(me, q) && g.hasFreeSlot(me)) {
          if (this.xAttack(g, 82, q, 'bossAssist')) { // ~8.0%B light assist with 36t cooldown!
            this.cmds++;
            this.lastAssistPokeTick = g.t;
            this.hitTo.set(q, g.t);
            if (typeof window !== "undefined" && window.__hlLog) {
              window.__hlLog(`[HL-ASSIST] t=${g.t} 10% boss-assist poke -> target=${q}(${g.names?.[q] || ""}) myBal=${B} dMe=${Math.round(dMe)}`);
            }
            return true;
          }
        }
      }
    }
    return false;
  }

  // UNIFIED ORGANISM: JOINT DEFENSE + TROOP PRODUCTION YIELD OPTIMIZER (t >= 1500 only):
  // Mathematical foundation:
  //   1) Early Game (t < 1500): Everyone expands on neutral land & AI bots with up to 7% compound interest.
  //      Paying 6.25% flat transfer tax before t=1500 destroys early compound growth -> ZERO transfers before t=1500!
  //   2) Marginal Troop Production Curve (t >= 1500):
  //      Total interest I(B) = r0 * B for d <= 100, and r0 * B * (3 - 2*d/100) for 100 < d <= 150.
  //      Taking the derivative dI/dB:
  //        - For d < 100: marginal yield is +1.00 * r0 (every troop produces maximum interest).
  //        - For d > 100: marginal yield is r0 * (3 - 4*d/100) -> NEGATIVE! (At d=110, -1.4*r0; at d=125, -2.0*r0!)
  //      Therefore, draining a rear bank down to d=35 destroys its troop production capacity (losing 65*L * r0 every 10 ticks),
  //      whereas keeping every territory in the [78*L, 100*L] sweet spot MAXIMIZES whole-squad troop production AND defense simultaneously!
  //   3) Transfer Trigger Condition (Marginal Gain > 6.25% Tax):
  tryDonateToTeammate(g, emergencyOnly = false) {
    const me = this.me;
    if (!g.teams || !(g.teams[me] > 0) || typeof g.donate !== "function") return false;
    // Rule #7671: Never transfer during the opening AI-bot phase (t < 1500)!
    if (g.t < 1500 || g.terr[me] < 1200 || g.bal[me] < 35000 || g.t - (this.lastDonateTick ?? -999) < 24) return false;
    const mySlot = typeof window !== "undefined" && Number.isInteger(window.__tsbSquadSlot) ? window.__tsbSquadSlot : (me % 10);
    if (!emergencyOnly && ((g.t / 5) | 0) % 5 !== (mySlot % 5)) return false;
    const B = g.bal[me], L = Math.max(1, g.terr[me]), dMe = B / L;

    let myHumanInAtk = 0, myHumanOutAtk = 0;
    for (const a of g.attackersOf(me)) {
      if (!g.isBot(a) && !this.isTeammate(g, a)) myHumanInAtk += g.attackTroopsOn(a, me);
    }
    const sbMe = g.slotBase(me);
    for (let i = 0; i < g.atkCount[me]; i++) {
      const tgt = g.atkTarget[sbMe + i];
      if (tgt >= 0 && tgt < g.humans && !g.isBot(tgt) && !this.isTeammate(g, tgt)) myHumanOutAtk += g.atkTroops[sbMe + i];
    }
    if (myHumanInAtk > 0 || myHumanOutAtk > 0.08 * B) return false;

    const enemyHumanNbs = this.nb.filter((p) => g.alive[p] && this.person(g, p));
    let anyEnemyNb = enemyHumanNbs.length > 0;
    if (!anyEnemyNb && this.cnt) {
      for (let p = 0; p < g.humans; p++) {
        if (p !== me && g.alive[p] && !this.isTeammate(g, p) && (this.cnt[p] ?? 0) > 0) {
          anyEnemyNb = true;
          break;
        }
      }
    }
    const boxedIn = !anyEnemyNb && this.nb.length === 0 && this.neutral === 0;
    const hasExposedCoast = (g.coast?.[me]?.length ?? 0) > 0;

    const bossId = this.findBossId(g);
    if (bossId >= 0 && g.alive[bossId] && g.terr[bossId] >= 100 && (!window.ao?.iD || window.ao.iD(bossId))) {
      const dBoss = g.bal[bossId] / Math.max(1, g.terr[bossId]);
      let bossInAtk = 0;
      for (const a of g.attackersOf(bossId)) bossInAtk += g.attackTroopsOn(a, bossId);
      const bossFloor = bossInAtk > 0 ? (boxedIn ? 40 * L : 72 * L) : (boxedIn ? 75 * L : 88 * L);
      if ((bossInAtk > 0 || dBoss < 112) && B > 1.15 * bossFloor) {
        const maxPct = Math.floor(((B - bossFloor) * 1024) / B);
        const pct = Math.min(maxPct, boxedIn ? 260 : 180);
        if (pct >= 120 && this.xDonate(g, pct, bossId, 'bossDonate')) {
          this.lastDonateTick = g.t;
          this.lastBossDonateTick = g.t;
          this.cmds++;
          return true;
        }
      }
    }

    // Production-optimal reserve floor (`prodOptFloor`):
    //   - Even a boxed-in rear bank MUST keep `76 * L` during normal play so its land produces maximum interest (`+r0` on 76*L)
    //     and only skims off the top when it hits `dMe >= 98` (right before the `100*L` negative-marginal-interest cliff)!
    //   - Frontline territory keeps `Math.max(86 * L, this.safeAt(g, -1))` and only skims off surplus when `dMe >= 106` (where marginal interest is negative `-1.24*r0`).
    const hasSeaEnemy = hasExposedCoast && (!this.p.enableQuotaExactDonate || !this.p.p6CoastFloor || this.seaPeople(g).length > 0);
    const prodOptFloor = boxedIn
      ? (hasSeaEnemy ? (this.p.enableQuotaExactDonate > 0 && this.p.p6CoastFloor > 0 ? this.p.p6CoastProdDens * L : 76 * L) : 70 * L)
      : Math.max(94 * L, this.safeAt(g, -1));

    const emergDefFloor = boxedIn
      ? (hasSeaEnemy ? (this.p.enableQuotaExactDonate > 0 && this.p.p6CoastFloor > 0 ? this.p.p6CoastEmergDens * L : 58 * L) : 48 * L)
      : Math.max(88 * L, this.safeAt(g, -1));

    let maxSquadTerr = 0, topSquadId = -1, maxRandomTeamTerr = 0;
    for (let p = 0; p < g.humans; p++) {
      if (!g.alive[p] || !this.isTeammate(g, p)) continue;
      if (typeof window !== "undefined" && window.__quitPlayers && window.__quitPlayers.has(p)) continue;
      if (this.isOurSquadBot(g, p) || this.isBossNpl(g, p)) {
        if (g.terr[p] > maxSquadTerr) {
          maxSquadTerr = g.terr[p];
          topSquadId = p;
        }
      } else if (!g.isBot(p) && g.terr[p] > maxRandomTeamTerr) {
        maxRandomTeamTerr = g.terr[p];
      }
    }
    let bestTarget = -1, bestScore = -Infinity, bestKind = "prod_opt", bestFloor = prodOptFloor;

    let totalSquadLandFronts = 0;
    for (let p = 0; p < g.humans; p++) {
      if (g.alive[p] && this.isTeammate(g, p) && (this.isOurSquadBot(g, p) || this.isBossNpl(g, p)) && g.terr[p] >= 150) {
        const nbs = this.peopleOf(g, p);
        if (nbs.some((o) => g.alive[o] && !this.isTeammate(g, o) && g.terr[o] > 0)) totalSquadLandFronts++;
      }
    }

    for (let p = 0; p < g.humans; p++) {
      if (p === me || !g.alive[p] || !this.isTeammate(g, p) || (!this.isOurSquadBot(g, p) && !this.isBossNpl(g, p)) || g.terr[p] < (totalSquadLandFronts <= 2 ? 150 : 1200)) continue;
      if (typeof window !== "undefined" && window.__quitPlayers && window.__quitPlayers.has(p)) continue;

      const Lp = Math.max(1, g.terr[p]), Bp = g.bal[p], dAlly = Bp / Lp;
      if (dAlly >= (boxedIn ? 142 : 115)) continue;
      if (this.p.enableQuotaExactDonate > 0 && this.p.p6AntiPingPong > 0 && this.p6IsPingPong(g, p)) {
        this.vCount("p6_pingpong_veto");
        continue;
      }
      if (this.p.enableQuotaExactDonate > 0 && this.p.p6QuotaExact > 0) {
        const minPct = this.p.p6MinDonatePct || 92;
        const capP = Math.min(Math.max(0, 142 * Lp - Bp - this.p6InflightTo(g, p)), this.p6MaxQuotaTroops(g, p));
        if (capP * 1024 < minPct * B) {
          this.vCount("p6_quota_veto");
          continue;
        }
      }

      let inHumanAtk = 0, outHumanAtk = 0;
      for (const a of g.attackersOf(p)) {
        if (!g.isBot(a) && !this.isTeammate(g, a)) inHumanAtk += g.attackTroopsOn(a, p);
      }
      const sbP = g.slotBase(p);
      for (let i = 0; i < g.atkCount[p]; i++) {
        const tgt = g.atkTarget[sbP + i];
        if (tgt >= 0 && tgt < g.humans && !g.isBot(tgt) && !this.isTeammate(g, tgt)) {
          outHumanAtk += g.atkTroops[sbP + i];
        }
      }

      const allyNbs = this.peopleOf(g, p);
      let enemyNbs = 0, botNbs = 0, minEnemyDens = Infinity, hasBleedingPrey = false;
      for (const o of allyNbs) {
        if (o !== me && g.alive[o] && !this.isTeammate(g, o) && g.terr[o] > 0) {
          const doDens = g.bal[o] / Math.max(1, g.terr[o]);
          if (!g.isBot(o)) {
            enemyNbs++;
            if (doDens < minEnemyDens) minEnemyDens = doDens;
            if (doDens < 45 || g.terr[o] <= 0.35 * (g.peak?.[o] ?? g.terr[o])) hasBleedingPrey = true;
          } else {
            botNbs++;
            if (doDens < minEnemyDens) minEnemyDens = doDens;
            if (doDens < 35) hasBleedingPrey = true;
          }
        }
      }
      if (enemyNbs === 0 && botNbs > 0) enemyNbs = botNbs;

      const allyHasCoast = (g.coast?.[p]?.length ?? 0) > 0;
      const isBeachhead = enemyNbs > 0 && totalSquadLandFronts <= 2 && boxedIn;
      const isCrownContender = (p === topSquadId && enemyNbs > 0 && maxRandomTeamTerr >= 0.70 * maxSquadTerr) || isBeachhead;
      if (enemyNbs === 0 && inHumanAtk === 0 && outHumanAtk === 0 && (!boxedIn || !allyHasCoast || dMe < 105 || dAlly > 112)) continue;

      let isDoomedPocket = !isBeachhead && (inHumanAtk > 1.65 * Bp || (g.t >= 4500 && Lp < 0.22 * maxSquadTerr && inHumanAtk > 0.45 * Bp));
      if (this.p.enableQuotaExactDonate > 0 && this.p.p6DeficitRescue > 0 && !isBeachhead) {
        const netDeficit = Math.max(0, 0.55 * inHumanAtk - Bp);
        const ourMaxGift = Math.max(0, B - emergDefFloor) * 0.9375;
        const wasDoomed = isDoomedPocket;
        isDoomedPocket = inHumanAtk > 2.2 * Bp || netDeficit > 1.8 * Math.max(1, ourMaxGift);
        if (wasDoomed && !isDoomedPocket) this.vCount("p6_deficit_save");
      }
      if (isDoomedPocket) continue;
      const underFire = inHumanAtk > 0 && (inHumanAtk >= 0.06 * Bp || dAlly < 88);
      const activePush = outHumanAtk >= 0.06 * Bp && dAlly < 96;
      const hasPreyOpening = enemyNbs > 0 && (hasBleedingPrey || minEnemyDens < 0.70 * dAlly) && dAlly < 96;

      if (emergencyOnly && !underFire) continue;

      if (underFire) {
        // Case A: Emergency 2:1 Defense Dispatch (strictly require dAlly < 85 and dMe >= dAlly + 15!)
        const reqD = boxedIn ? (hasExposedCoast ? 68 : 58) : 102;
        if (dMe < reqD || dAlly >= 85 || B <= 1.12 * emergDefFloor || dMe < dAlly + 15) continue;
        const score = 5000 + (inHumanAtk / Math.max(1, Bp)) * 1200 + (105 - dAlly) * 20 + Math.min(2200, Lp / 18);
        if (score > bestScore) {
          bestScore = score;
          bestTarget = p;
          bestKind = "defense_dispatch";
          bestFloor = emergDefFloor;
        }
      } else {
        // Case B: Joint Production + Offense Yield Optimization
        // Donor MUST be at or above the 100*L negative-marginal-interest threshold (`dMe >= 98` if boxedIn, `dMe >= 106` if frontline)
        // AND Recipient must be below 92*L so moving troops from Donor -> Recipient shifts troops from NEGATIVE marginal interest (-1.4*r0)
        // to POSITIVE +1.0*r0 full interest + frontline defense/offense!
        const reqD = boxedIn ? 96 : 108;
        const maxAllyD = boxedIn ? (activePush || hasPreyOpening || enemyNbs > 0 ? 94 : 88) : 88;
        if (dMe < reqD || dAlly > maxAllyD || B <= 1.14 * prodOptFloor || dMe < dAlly + 15) continue;
        const score = (activePush || hasPreyOpening ? 2500 : 1000) +
          (isCrownContender ? 1800 : 0) +
          (outHumanAtk / Math.max(1, Bp)) * 1200 +
          (hasBleedingPrey ? 500 : 0) +
          (100 - dAlly) * 18 +
          enemyNbs * 80 +
          Math.min(3500, Lp / 14);
        if (score > bestScore) {
          bestScore = score;
          bestTarget = p;
          bestKind = activePush || hasPreyOpening ? "offense_dispatch" : "yield_opt_dispatch";
          bestFloor = prodOptFloor;
        }
      }
    }

    if (bestTarget < 0) return false;

    const maxSurplus = Math.max(0, B - bestFloor);
    let maxTransfer = maxSurplus;
    let idealPct = bestKind === "defense_dispatch"
      ? (boxedIn ? 260 : 190)
      : (boxedIn ? 220 : 170);
    if (this.p.enableQuotaExactDonate > 0 && this.p.p6QuotaExact > 0) {
      const LpT = Math.max(1, g.terr[bestTarget]), BpT = g.bal[bestTarget];
      const recipRoom = Math.max(0, 142 * LpT - BpT - this.p6InflightTo(g, bestTarget));
      const quotaMax = this.p6MaxQuotaTroops(g, bestTarget);
      maxTransfer = Math.min(maxSurplus, recipRoom, quotaMax);
      idealPct = bestKind === "defense_dispatch"
        ? (boxedIn ? 420 : 310)
        : (boxedIn ? 360 : 260);
    }
    const maxSafePct = Math.floor((maxTransfer * 1024) / Math.max(1, B));
    const pct = Math.min(maxSafePct, idealPct);
    const minPct = this.p.enableQuotaExactDonate > 0 && this.p.p6QuotaExact > 0 ? (this.p.p6MinDonatePct || 92) : 150;
    if (pct < minPct) {
      if (maxSurplus * 1024 >= minPct * B) this.vCount("p6_quota_veto");
      return false;
    }

    if (this.xDonate(g, pct, bestTarget, bestKind)) {
      this.p6RecordDonate(g, bestTarget, iV(B * (pct + 1), 1024));
      this.lastDonateTick = g.t;
      this.cmds++;
      if (typeof window !== "undefined" && window.__hlLog) {
        const dTarget = Math.round(g.bal[bestTarget] / Math.max(1, g.terr[bestTarget]));
        window.__hlLog(`[HL-DISPATCH] t=${g.t} ${bestKind} pct=${pct}/1024 -> ally=${bestTarget}(${g.names?.[bestTarget] || ""}) boxedIn=${boxedIn} myBal=${B} dMe=${Math.round(dMe)} dAlly=${dTarget}`);
      }
      return true;
    }
    return false;
  }

  isMopUp(g) {
    const me = this.me;
    if (g.teams && g.teams[me] > 0) {
      let enemyAlive = false;
      for (let p = 0; p < g.players; p++) {
        if (g.alive[p] && g.terr[p] > 0 && g.teams[p] !== g.teams[me]) {
          enemyAlive = true;
          break;
        }
      }
      if (!enemyAlive && this.nb.length === 0 && this.neutral === 0) return true;
    }
    return this.nb.length === 0 && this.neutral === 0 && g.terr[me] >= 0.80 * g.land && this.livingHumanCount(g) <= 1;
  }

  spawnWeight(g, s) {
    const w = super.spawnWeight ? super.spawnWeight(g, s) : 1;
    const comp = this.compSize(g);
    const sz = comp?.[s] ?? g.land;
    if (sz > 0 && sz < 15000 && sz < 0.25 * g.land) return w * 0.25;
    return w;
  }

  safeAt(g, q) {
    let s = super.safeAt(g, q);
    const P = this.p, me = this.me, L = Math.max(1, g.terr[me]);
    s = Math.min(s, P.oppFloorCap * L);
    if (q < 0 || !this.person(g, q)) {
      s = Math.min(s, P.oppFloorCap * L);
    } else if (P.a06AloneSafe > 0 && !this.isNoFullSend && g.t >= 4800 && g.attackTroopsOn(q, me) === 0 && g.bal[q] > 0.10 * g.bal[me]) {
      for (const p of this.nb) {
        if (p === q || !g.alive[p] || !this.person(g, p) || g.bal[p] <= 1.15 * g.bal[me]) continue;
        const pOthers = this.peopleOf(g, p).filter((o) => o !== me && g.alive[o] && g.terr[o] > 0);
        if (pOthers.length === 0) {
          const coalitionKeep = Math.max(0, (g.bal[p] + 0.45 * g.bal[q] - 1.5 * L) / 1.78);
          s = Math.max(s, coalitionKeep);
        }
      }
    }
    return s;
  }

  winFloor(g, q) {
    if (this.sbT !== g.t) {
      this.sbT = g.t;
      this.sb = this.safeFinite(g);
    }
    const P = this.p, me = this.me, L = Math.max(1, g.terr[me]);
    const mult = this.contested(g, q) ? P.sharedBotMult : 1.0;
    const price = (mult * this.botPx(g, q) * L) / (P.winR * Math.max(1, g.t));
    const guard = Math.max(this.dpKeep(g), this.sb);
    return Math.max(price, guard);
  }

  hasBorderFood(g) {
    if (this.neutral > 0) return true;
    for (const q of this.nb) {
      if (g.alive[q] && g.terr[q] > 0 && !this.person(g, q)) return true;
    }
    return false;
  }

  newHumansExposed(g, q) {
    const me = this.me;
    let newCnt = 0;
    for (const o of this.peopleOf(g, q)) {
      if (o !== me && g.alive[o] && g.terr[o] > 0 && !this.nb.includes(o)) {
        newCnt++;
      }
    }
    return newCnt;
  }

  activeFocus(g) {
    const P = this.p;
    if (!(P.focusBonus < 1)) return -1;
    let bestQ = -1, bestT = g.t - P.focusT;
    for (const q of this.nb) {
      if (!g.alive[q] || !this.person(g, q) || (this.cnt[q] ?? 0) < 25) continue;
      const t = this.hitTo.get(q) ?? -1e9;
      if (t > bestT) {
        bestT = t;
        bestQ = q;
      }
    }
    return bestQ;
  }

  peerAggressor(g) {
    const P = this.p, me = this.me, B = g.bal[me];
    for (const q of this.nb) {
      if (!g.alive[q] || !this.person(g, q)) continue;
      const inc = g.attackTroopsOn(q, me);
      if (inc > Math.max(500, 0.02 * B)) {
        this.hitFrom.set(q, g.t);
      }
    }
    if (!(P.defendDiscount < 1) || g.t < P.defendFrom) return -1;
    if (P.absorbMode === 1) {
      let bestQ = -1, bestT = g.t - P.absorbMemory;
      for (const q of this.nb) {
        if (!g.alive[q] || !this.person(g, q) || (this.cnt[q] ?? 0) < 25) continue;
        const inc = g.attackTroopsOn(q, me);
        const t = this.hitFrom.get(q) ?? -1e9;
        if (inc < 0.015 * B && t > bestT && g.bal[q] + inc <= 1.4 * B) {
          bestT = t;
          bestQ = q;
        }
      }
      return bestQ;
    }
    let bestQ = -1, bestIn = 0;
    for (const q of this.nb) {
      if (!g.alive[q] || !this.person(g, q)) continue;
      const inc = g.attackTroopsOn(q, me);
      if (P.counterClearMode >= 5 && inc > P.pulseFrac * B + g.attackTroopsOn(me, q)) continue;
      if (inc > Math.max(500, 0.02 * B) && g.bal[q] + inc <= 1.6 * B && inc > bestIn) {
        bestIn = inc;
        bestQ = q;
      }
    }
    if (bestQ < 0 && P.aggMemMode >= 1) {
      let bestT = g.t - 150;
      for (const q of this.nb) {
        if (!g.alive[q] || !this.person(g, q) || (this.cnt[q] ?? 0) < 25) continue;
        const inc = g.attackTroopsOn(q, me);
        if (inc > P.pulseFrac * B + g.attackTroopsOn(me, q)) continue;
        const t = this.hitFrom.get(q) ?? -1e9;
        if (t > bestT && g.bal[q] + inc <= 1.5 * B) {
          bestT = t;
          bestQ = q;
        }
      }
    }
    return bestQ;
  }

  stepFlashLoan(g) {
    const P = this.p, me = this.me;
    const st = this.flState;
    if (!st) return false;
    if (g.t > st.expireTick) {
      if (st.phase === 'wait_expand' && g.hasAttack(me, st.E)) {
        this.xRetreat(g, st.E, 'flashLoan');
      }
      this.flState = null;
      return false;
    }

    if (st.phase === 'armed') {
      const waitGoal = g.online ? 3 : 7;
      if (g.t >= st.armTick + waitGoal) {
        if (!g.alive[st.E] || g.bal[me] > 142 * g.terr[me]) {
          this.flState = null;
          return false;
        }
        if (this.xAttack(g, 1023, st.E, 'flashLoan')) {
          this.cmds++;
          if (!g.online && st.extraTargets?.length) {
            for (const b of st.extraTargets) {
              if (g.alive[b] && g.attackTroopsOn(b, me) === 0 && !g.hasAttack(me, b) && g.hasFreeSlot(me)) {
                this.xAttack(g, 0, b, 'flashLoan');
                this.cmds++;
              }
            }
          }
          st.phase = 'wait_expand';
          st.parkTick = g.t;
          return true;
        }
      }
      return false;
    }

    if (st.phase === 'wait_expand') {
      let bFresh = false;
      const base = g.slotBase(me);
      for (let i = g.atkCount[me] - 1; i >= 0; i--) {
        if (g.atkTarget[base + i] === st.B1 && g.atkFresh[base + i] === 1) {
          bFresh = true;
          break;
        }
      }
      if (!bFresh || g.t >= st.armTick + 9) {
        if (g.hasAttack(me, st.E)) {
          if (this.xRetreat(g, st.E, 'flashLoan')) {
            this.cmds++;
            this.flStats.runs++;
            this.flStats.printed += st.estPrint;
            this.flStats.targets += 1 + (st.extraTargets?.length ?? 0);
            this.lastFlashLoan = g.t;
            this.flState = null;
            return true;
          }
        } else {
          this.flState = null;
        }
      }
      return false;
    }
    return false;
  }

  tryStartFlashLoan(g) {
    const P = this.p, me = this.me;
    if (!(P.flashLoanMode > 0) || this.flState || g.t < 2000 || g.t - this.lastFlashLoan < 45) return false;
    if (g.atkCount[me] > 0) return false; // Must be unscheduled so schedWait starts cleanly at 64 -> 6!
    const B = g.bal[me], L = Math.max(1, g.terr[me]);
    if (B < 80000 || B > 140 * L) return false;
    for (const a of g.attackersOf(me)) if (a < g.humans && !g.isBot(a)) return false;

    if (P.flashLoanMode === 3) {
      const humanNbs = this.nb.filter((p) => g.alive[p] && this.person(g, p));
      const botNbs = this.nb.filter((p) => g.alive[p] && !this.person(g, p) && g.bal[p] > 5000);
      if (humanNbs.length > 1 || botNbs.length > 0) return false;
    }

    const fee = iV(12 * B, 1024);
    let parkE = -1, parkScore = Infinity;
    if (this.neutral >= 4) {
      parkE = NEUTRAL;
      parkScore = 0;
    } else {
      for (const q of this.nb) {
        if (!g.alive[q] || !g.terr[q] || g.attackTroopsOn(q, me) > 0) continue;
        if (!this.person(g, q) && (this.cnt[q] ?? 0) >= 3) {
          const s = g.bal[q];
          if (s < parkScore) {
            parkScore = s;
            parkE = q;
          }
        }
      }
    }
    if (parkE < 0 && P.flashLoanMode >= 2) {
      for (const q of this.nb) {
        if (!g.alive[q] || !this.person(g, q) || g.attackTroopsOn(q, me) > 0) continue;
        if ((this.cnt[q] ?? 0) >= 8 && g.bal[q] < 0.7 * B) {
          if (g.bal[q] < parkScore) {
            parkScore = g.bal[q];
            parkE = q;
          }
        }
      }
    }
    if (parkE < 0) return false;

    const cands = [];
    for (const q of this.nb) {
      if (q === parkE || !g.alive[q] || !this.person(g, q) || g.attackTroopsOn(q, me) > 0) continue;
      const cntQ = this.cnt[q] ?? 0;
      if (cntQ < 16) continue;
      const def = iV(cntQ * g.bal[q], 1 + iV(10 * g.terr[q], 16));
      const ring1Cost = cntQ * 2 + 2 * def + 1;
      if (ring1Cost >= P.flashLoanMinCost && ring1Cost >= P.flashLoanMinRatio * (62500 + 2 * fee)) {
        cands.push({ q, cost: ring1Cost });
      }
    }
    if (!cands.length) return false;
    cands.sort((a, b) => b.cost - a.cost);
    const B1 = cands[0].q;
    const extraTargets = !g.online && P.flashLoanMode >= 2 ? cands.slice(1, 3).map((x) => x.q) : [];
    const estPrint = cands.slice(0, 1 + extraTargets.length).reduce((s, x) => s + x.cost, 0);

    if (this.xAttack(g, 0, B1, 'flashLoan')) {
      this.cmds++;
      this.hitTo.set(B1, g.t);
      this.flState = {
        phase: 'armed',
        armTick: g.t,
        expireTick: g.t + 16,
        B1,
        E: parkE,
        extraTargets,
        estPrint,
      };
      return true;
    }
    return false;
  }

  // v28/P8: nothing thrown inside a tick may reach the bridge (the bridge would lose the whole tick,
  // and with it every later step of this seat).
  act(g) {
    const P = this.p;
    if (!(P.enableCollapseGuard > 0 && P.p8Isolate > 0)) return this.actCore(g);
    try {
      this.actCore(g);
    } catch (e) {
      this.vFault(g, "act", e);
    }
  }

  actCore(g) {
    const P = this.p, me = this.me;
    if (this.v28Any) this.safeStep(g, "vTick", () => this.vTick(g));
    if (!g.canAct(me)) return;
    if (P.quotaGuardMode > 0) this.safeStep(g, "shadowQuota", () => this.updateShadowQuota(g));

    // 0. Every single tick: step the 50k debt cap flash-loan state machine if active!
    if (P.flashLoanMode > 0 && this.flState) {
      if (this.stepFlashLoan(g) && g.online) return;
      if (this.flState) return; // Hold normal decisions during the 8-tick flash-loan window!
    }

    // 1. Every single tick: check 2-tick `P_BORDER` bridgehead handoffs (#6 / #8)!
    if (P.seaCore > 0 && this.seaState.pendingHandoffs.size > 0) {
      this.safeStep(g, "handoff", () => handoffFootholds(g, me, this.seaState, (gm, q) => this.safeAt(gm, q)));
    }

    // 2. Combo 1 (#2): In online `LiveGame` (where only 1 command can be sent per tick),
    // if the previous tick (`g.t - 1`) just executed a major land spend that dropped `bal[me]` to a dip,
    // use this off-period tick `t + 1` to launch our cheap stepping-stone boat!
    if (
      P.seaCore > 0 &&
      g.online &&
      g.t - this.lastLandSpendTick === 1 &&
      g.t >= 750 &&
      this.neutral === 0 &&
      g.t - this.seaState.lastFrogHop >= 35 &&
      g.canAct(me)
    ) {
      const B = g.bal[me], fee = iV(32 * B, 1024);
      if (fee <= 500 && frogHopStep(g, me, this.seaState, { maxHopBoats: 1, maxTotalBoats: 4, maxAbsCost: 550 })) {
        this.seaState.lastFrogHop = g.t;
        this.seaState.stats.froghop.boats++;
        this.seaState.stats.froghop.fee += fee;
        return;
      }
    }

    if (!this.isTurn(g)) return;
    this.vKeepNext = null;
    if (g.t < P.coreFrom) {
      this.analyze(g);
      if (typeof window !== "undefined" && window.__hlLog && g.t > 0 && g.t % 90 === 0 && this._lastTickLog !== g.t) {
        this._lastTickLog = g.t;
        const pf = window.__hlPerf;
        const pfStr = pf && pf.ticks > 0 ? ` avgMs=${(pf.totalMs / pf.ticks).toFixed(2)} maxMs=${pf.maxMs.toFixed(1)} skip=${pf.skippedTicks}` : "";
        window.__hlLog(`[HL-TICK] t=${g.t} terr=${g.terr[me]}(${(100 * g.terr[me] / Math.max(1, g.land)).toFixed(1)}%) bal=${g.bal[me]} dens=${(g.bal[me] / Math.max(1, g.terr[me])).toFixed(1)} nb=${this.nb.length} neut=${this.neutral} cmds=${this.cmds} boats=${this.boats}${pfStr}`);
      }
      if (this.safeStep(g, "bossRescue", () => this.tryEmergencyBossRescue(g)) && g.online) return;
      if (this.safeStep(g, "lifeGuard", () => this.lifeGuardAct(g))) return;
      const before = this.cmds;
      const balBefore = g.bal[me];
      this.safeStep(g, "earlyAct", () => super.act(g));
      if (this.cmds > before && g.bal[me] <= 0.75 * balBefore) {
        this.lastLandSpendTick = g.t;
      }
      // Line 1: Independent Island-Hopping Line (#2475 / #2477 / #3475):
      if (
        P.seaCore > 0 &&
        g.t >= 750 &&
        this.neutral === 0 &&
        (!g.online || this.cmds === before) &&
        g.canAct(me) &&
        g.t % P.period === 0 &&
        g.t - this.seaState.lastFrogHop >= 35
      ) {
        this.analyze(g);
        const B = g.bal[me];
        const trapped = !this.hasBorderFood(g);
        const lowDip = (!g.online && this.cmds > before && B <= 0.75 * balBefore) || B <= 8000;
        if (trapped || lowDip) {
          const fee = iV(32 * B, 1024);
          const maxAbsCost = trapped ? 1500 : 550;
          if (frogHopStep(g, me, this.seaState, { maxHopBoats: 1, maxTotalBoats: 4, maxAbsCost })) {
            this.seaState.lastFrogHop = g.t;
            this.seaState.stats.froghop.boats++;
            this.seaState.stats.froghop.fee += fee;
          }
        }
      }
      return;
    }
    if (!this.isTurn(g)) return;

    this.analyze(g);
    if (typeof window !== "undefined" && window.__hlLog && g.t > 0 && g.t % 90 === 0 && this._lastTickLog !== g.t) {
      this._lastTickLog = g.t;
      const pf = window.__hlPerf;
      const pfStr = pf && pf.ticks > 0 ? ` avgMs=${(pf.totalMs / pf.ticks).toFixed(2)} maxMs=${pf.maxMs.toFixed(1)} skip=${pf.skippedTicks}` : "";
      window.__hlLog(`[HL-TICK] t=${g.t} terr=${g.terr[me]}(${(100 * g.terr[me] / Math.max(1, g.land)).toFixed(1)}%) bal=${g.bal[me]} dens=${(g.bal[me] / Math.max(1, g.terr[me])).toFixed(1)} nb=${this.nb.length} neut=${this.neutral} cmds=${this.cmds} boats=${this.boats}${pfStr}`);
      if (g.t < (window.__lastReplaySnapAt || 0)) window.__lastReplaySnapAt = 0; if (g.t >= 2700 && g.t - (window.__lastReplaySnapAt || 0) >= 630 && typeof bC === "object" && bC?.a7s?.a2b) {
        let minAliveSquadId = me;
        for (let p = 0; p < g.humans; p++) {
          if (g.alive[p] && this.isTeammate(g, p) && this.isOurSquadBot(g, p) && p < minAliveSquadId) minAliveSquadId = p;
        }
        if (me === minAliveSquadId) {
          window.__lastReplaySnapAt = g.t;
          try {
            const repStr = bC.a7s.a2b();
            if (typeof repStr === "string" && repStr.length > 100) {
              const fullUrl = repStr.indexOf("=") >= 0 ? repStr : ("https://territorial.io/?replay=" + repStr);
              window.__hlLog("[HL-LIVE-REPLAY-URL] " + fullUrl);
              const eqIdx = repStr.indexOf("=");
              const rawClean = (eqIdx >= 0 ? repStr.slice(eqIdx + 1) : repStr).trim();
              if (typeof window.__tsbReportResult === "function") {
                const seedTag = (typeof aE === "object" && aE?.data?.mapSeed) ? aE.data.mapSeed : "live";
                window.__tsbReportResult(JSON.stringify({ type: "replay", game: "raw-seed" + seedTag + "-t" + g.t, replay: rawClean }));
              }
            }
          } catch {}
        }
      }
    }
    this.safeStep(g, "peaceVote", () => this.tryPeaceVote(g));
    if (g.t > 8500 && g.terr[me] < 0.04 * Math.max(1, g.land)) {
      let aliveBros = 0, sumBroTerr = 0;
      for (let p = 0; p < g.humans; p++) {
        if (g.alive[p] && this.isTeammate(g, p) && this.isOurSquadBot(g, p) && g.terr[p] >= 80) {
          aliveBros++;
          sumBroTerr += g.terr[p];
        }
      }
      if (aliveBros <= 2 && sumBroTerr < 0.05 * Math.max(1, g.land)) {
        try {
          const d = window.dictionary, gm = d && window[d.game];
          if (gm && gm[d.sbLeave] && gm[d.gameState] !== 0) gm[d.sbLeave](true);
        } catch {}
        return;
      }
    }
    if (this.safeStep(g, "bossRescue", () => this.tryEmergencyBossRescue(g)) && g.online) return;
    this.safeStep(g, "wars", () => {
      this.updateGrudges(g);
      this.updateWars(g);
    });

    // v28/P8: near our own collapse line the guard goes first (one command, then the tick is over).
    if (this.safeStep(g, "lifeGuard", () => this.lifeGuardAct(g))) return;

    // (e.g. from eating an adjacent bot or a secondary boat step) and our slot is large enough,
    // re-ignite those borders!
    if (P.seaCore > 0 && P.reigniteBorders > 0) {
      if (this.safeStep(g, "reignite", () => reigniteNewBorders(g, me, this.seaState, this.cnt, P.reigniteMinShare)) && g.online) return;
    }

    const cmdsBefore = this.cmds;
    if (P.flashLoanMode > 0 && this.safeStep(g, "flashLoan", () => this.tryStartFlashLoan(g))) return;
    // v28/P1 arbitration: with only a few neutral pixels left, land worth its price (or an attacker to
    // answer) goes before the neutral top-up; the top-up and the rest of buyLand follow only when
    // that sent nothing.
    let boughtFirst = false;
    if (P.enableInflightLedger > 0 && P.p1Arbitrate > 0 && g.t >= P.dpEnd && this.neutral > 0 && this.neutral <= P.p1ArbNeutral) {
      this.buyQuality = true;
      this.safeStep(g, "buyLandFirst", () => this.buyLand(g));
      this.buyQuality = false;
      boughtFirst = this.cmds !== cmdsBefore;
      if (boughtFirst) this.vCount("p1_arb_buy_first");
    }
    if (this.neutral > 0 && !boughtFirst) this.safeStep(g, "expandNeutral", () => this.expandNeutral(g, g.bal[me] - this.safeAt(g, -1)));
    if (!boughtFirst) this.safeStep(g, "buyLand", () => this.buyLand(g));

    if (P.seaCore > 0 && g.t - this.seaState.lastWiden >= 30) {
      const fee = iV(32 * g.bal[me], 1024);
      if (
        this.safeStep(g, "widenFront", () => widenFrontBoats(g, me, this.seaState, this.cnt, {
          maxFront: 22,
          minSteps: P.widenStepsMin ?? 0,
          minAtkShare: 0.08,
          maxBoats: 5,
          atkFreshBoats: P.atkFreshBoats > 0,
          baseRatePer10: P.seaRebateMode > 0 ? this.baseRate(g) : 0,
        }))
      ) {
        this.seaState.lastWiden = g.t;
        this.seaState.stats.widen.boats++;
        this.seaState.stats.widen.fee += fee;
      }
    }

    if (this.cmds === cmdsBefore) this.safeStep(g, "donate", () => this.tryDonateToTeammate(g));
    if (this.cmds === cmdsBefore) this.safeStep(g, "idleBoats", () => this.idleBoats(g));

    // Line 1: Independent Island-Hopping Line ("算账再发" cost-benefit gate):
    if (P.seaCore > 0 && g.t - this.seaState.lastFrogHop >= 30) {
      const B = g.bal[me], L = Math.max(1, g.terr[me]), fee = iV(32 * B, 1024);
      const negInterestCap = P.frogHopOverMode > 0 && B >= 112 * L ? Math.min(25000, Math.floor(0.036 * B)) : 550;
      const maxAbsCost = !this.hasBorderFood(g) ? Math.max(1800, negInterestCap) : negInterestCap;
      if (
        this.safeStep(g, "frogHop", () => frogHopStep(g, me, this.seaState, {
          maxHopBoats: 2,
          maxTotalBoats: 5,
          maxAbsCost,
          safeFloor: this.safeAt(g, -1),
          botPhaseMode: P.botPhaseMode > 0,
        }))
      ) {
        this.seaState.lastFrogHop = g.t;
        this.seaState.stats.froghop.boats++;
        this.seaState.stats.froghop.fee += fee;
      }
    }
  }

  compSize(g) {
    if (!(this.p.seaFree > 0) || g.t < this.p.coreFrom) return super.compSize(g);
    if (this.freeAt === g.t) return this.freeComp;
    const N = g.N, px = g.px, own = g.own, d = g.dir4, me = this.me;
    const c = this.freeComp?.length === N ? this.freeComp.fill(0) : new Int32Array(N);
    const seen = new Uint8Array(N), q = new Int32Array(N);
    for (let s = 0; s < N; s++) {
      if (px[s] !== T_LAND || seen[s]) continue;
      let h = 0, t = 0, taken = false;
      q[t++] = s;
      seen[s] = 1;
      while (h < t) {
        const a = q[h++];
        for (let k = 0; k < 4; k++) {
          const n = a + d[k];
          if (n < 0 || n >= N) continue;
          const v = px[n];
          if (v === T_LAND) {
            if (!seen[n]) {
              seen[n] = 1;
              q[t++] = n;
            }
          } else if (v >= P_INNER && own[n] !== me) taken = true;
        }
      }
      const effSize = !taken ? t : t >= 120 ? Math.max(100, t >> 1) : 0;
      if (effSize > 0) for (let i = 0; i < t; i++) c[q[i]] = effSize;
    }
    this.freeAt = g.t;
    this.freeComp = c;
    return c;
  }

  idleBoats(g) {
    const P = this.p, me = this.me;
    const B = g.bal[me], L = Math.max(1, g.terr[me]), dMe = B / L;
    if (this.nb.length === 0 && this.neutral === 0 && g.teams && g.teams[me] > 0 && !this.isMopUp(g)) {
      if (P.enableSeaPrecision > 0 && P.p7BoxedBreakout > 0 && P.boatFood > 0 && dMe >= 42 && this.boatFood(g)) {
        this.vCount("p7_boxed_food");
        return;
      }
      let activeLandFrontBrothers = 0;
      for (let p = 0; p < g.humans; p++) {
        if (p !== me && g.alive[p] && this.isTeammate(g, p) && (this.isOurSquadBot(g, p) || this.isBossNpl(g, p)) && g.terr[p] >= 500) {
          if (typeof window !== "undefined" && window.__quitPlayers && window.__quitPlayers.has(p)) continue;
          const nbs = this.peopleOf(g, p);
          if (nbs.some((o) => g.alive[o] && !this.isTeammate(g, o) && g.terr[o] > 0)) activeLandFrontBrothers++;
        }
      }
      const boxedBreakout = P.enableSeaPrecision > 0 && P.p7BoxedBreakout > 0 && this.boxedSinceT >= 0 && g.t - this.boxedSinceT >= P.p7BoxedTicks;
      const reqIdleDens = boxedBreakout ? P.p7BoxedDens : 115;
      if (activeLandFrontBrothers >= 1 && dMe < reqIdleDens) return;
      if (!g.boatsAllowed(me) || g.boatCount[me] >= 6) return;
      if (g.t - this.lastBoat < Math.min(P.boatEvery, 18)) return;
      const { floorAt } = this.floors(g);
      const keepFloor = activeLandFrontBrothers >= 1 ? (boxedBreakout && dMe < 115 ? 72 * L : 92 * L) : 68 * L;
      const oldRange = P.boatRange;
      const oldFrac = P.boatFrac;
      P.boatRange = boxedBreakout && dMe < 115 ? 450 : 2500;
      P.boatFrac = Math.max(oldFrac, 0.24);
      if (boxedBreakout && dMe < 115) this.vCount("p7_boxed_breakout");
      this.boatOut(g, (price) => Math.max(Math.min(floorAt(price), 85 * L), keepFloor), Infinity);
      P.boatRange = oldRange;
      P.boatFrac = oldFrac;
      return;
    }
    if (this.isMopUp(g)) {
      if (!g.boatsAllowed(me) || g.boatCount[me] >= 6) return;
      const oldRange = P.boatRange;
      P.boatRange = 2500;
      this.boatOut(g, () => 0, Infinity);
      P.boatRange = oldRange;
      return;
    }
    if (P.a06BoatUnderAtk > 0 && g.t >= 3500 && g.bal[me] < 100 * g.terr[me]) {
      let humanInAtk = 0;
      for (const a of g.attackersOf(me)) if (a < g.humans && !g.isBot(a)) humanInAtk += g.attackTroopsOn(a, me);
      if (humanInAtk >= 0.06 * g.bal[me]) return;
    }
    if (P.boatFood > 0 && this.boatFood(g)) return;
    if (this.neutral > 0 || g.t - this.lastBoat < P.boatEvery) return;
    if (this.nb.length && g.bal[me] < P.idleCap * 100 * g.terr[me]) return;
    const { floorAt } = this.floors(g);
    let activeHops = 0;
    if (this.seaState.inFlightIsles) {
      for (const [, expT] of this.seaState.inFlightIsles) if (g.t < expT) activeHops++;
    }
    const oldMax = P.maxBoats;
    P.maxBoats = oldMax + activeHops;
    this.boatOut(g, floorAt, P.boatFee > 0 && this.nb.length ? P.boatFee * this.minNbPrice(g) : Infinity);
    P.maxBoats = oldMax;
  }

  offers(g) {
    const P = this.p, me = this.me;
    let active = 0;
    const base = g.slotBase(me);
    for (let i = g.atkCount[me] - 1; i >= 0; i--) if (g.atkTarget[base + i] !== NEUTRAL) active++;
    const B = g.bal[me], L = Math.max(1, g.terr[me]), dMe = B / L, fee = iV(12 * B, 1024);
    const dMed = this.otherHumanMedDens(g) ?? dMe;
    const nHumans = this.livingHumanCount(g);
    const humanNbs = this.nb.filter((p) => g.alive[p] && this.person(g, p));
    const focusQ = this.activeFocus(g);
    const aggQ = this.peerAggressor(g);
    const topRival = this.topOtherHuman(g);
    const out = [];

    for (const q of this.nb) {
      if (!g.alive[q] || !g.terr[q]) continue;
      const already = g.hasAttack(me, q);
      if (!already && (active >= P.maxTargets || !g.hasFreeSlot(me))) continue;

      const Lq = g.terr[q], Bq = g.bal[q], dq = Bq / Math.max(1, Lq);
      const person = this.person(g, q);
      const inAtk = g.attackTroopsOn(q, me);
      // v28/P1: troops of ours on q that have left but not landed count as already there (need_eff)
      const myAtk = g.attackTroopsOn(me, q) + this.inflightOn(g, q);
      const rawNeed = this.elimCost(g, q) + inAtk - myAtk;
      if (rawNeed <= 0) continue;
      const left = iV(g.peak[q], 4);
      const share = Math.min(1, this.cnt[q] / Math.max(1, g.border[q].length));
      const baseGain = Math.max(1, Lq - left + left * P.shareW * share);
      let c = (rawNeed + fee) / baseGain;

      if (!person) {
        out.push({
          q,
          person: false,
          tD: dq / Math.max(0.1, dMed),
          need: rawNeed,
          c,
          rankC: c,
          pulseMode: false,
          nearCollapse: false,
          bleeding: false,
        });
      } else {
        const tD = dq / Math.max(0.1, dMed);
        const bossId = this.findBossId(g);
        let otherAtk = 0, otherAtkers = 0, allyAtk = 0, clanAllyAtkers = 0, bossAtkOnQ = 0, randomTeamAtk = 0;
        for (const a of g.attackersOf(q)) {
          if (a !== me && !g.isBot(a)) {
            const tr = g.attackTroopsOn(a, q);
            otherAtkers++;
            otherAtk += tr;
            if (a === bossId) bossAtkOnQ += tr;
            if (this.isTeammate(g, a)) {
              allyAtk += tr;
              if (this.isOurSquadBot(g, a) || a === bossId) {
                clanAllyAtkers += 2;
              } else {
                randomTeamAtk += tr;
              }
            }
          }
        }
        let atkOnAlly = 0, atkOnBoss = 0;
        if (g.teams && g.teams[me] > 0) {
          const sbQ = g.slotBase(q);
          for (let i = 0; i < g.atkCount[q]; i++) {
            const tgt = g.atkTarget[sbQ + i];
            if (tgt >= 0 && tgt < 512 && this.isTeammate(g, tgt)) {
              const tr = g.atkTroops[sbQ + i];
              atkOnAlly += tr;
              if (tgt === bossId) atkOnBoss += tr;
            }
          }
        }
        const emptyAllIn = P.emptyAllInMode > 0 && inAtk > 0.15 * B && Bq < 0.08 * inAtk && tD < 0.06 && Lq >= 5000;
        const nearCollapse = Lq <= P.collapseRatio * left || (otherAtk > 0 && otherAtk >= 0.65 * rawNeed) || emptyAllIn;
        const bleeding = (otherAtkers > 0 && (tD < 0.75 || otherAtk >= 0.15 * Bq)) || emptyAllIn;
        const onMe = inAtk > 0;

        if (nearCollapse) {
          const effNeed = emptyAllIn ? Math.max(1, this.elimCost(g, q)) : rawNeed;
          const pulseBudget = Math.max(fee * 4, Math.min(0.12 * B, effNeed));
          const expectedFree = P.enableCoordinatedStrike > 0 && P.p4CollapseDenom > 0 && Lq - left < 0.15 * Lq
            ? Math.max(100, Lq * Math.max(0.25, share))
            : Math.max(100, (Lq - left) * share + left * Math.max(0.20, share));
          c = Math.min(c, (pulseBudget + fee) / expectedFree + 2 + 0.8 * dq);
        } else if (bleeding) {
          c *= P.bleedDiscount;
        } else if (P.thinDiscount < 1 && tD < P.thinMaxTD && dq < 0.65 * dMe) {
          c *= P.thinDiscount;
        }

        const isStaleHardAgg =
          P.a06AggMemGate > 0 &&
          !this.isNoFullSend &&
          g.t >= 4800 &&
          !onMe &&
          humanNbs.length >= 3 &&
          rawNeed > 0.65 * B &&
          dq > 0.80 * dMe;

        if (q === aggQ && !nearCollapse && !isStaleHardAgg) {
          const baseNeedNoIn = Math.max(1, this.elimCost(g, q) - myAtk);
          const defDisc = g.t < 4200 && B <= 100 * L ? P.defendDiscountMid : P.defendDiscount;
          c = Math.min(c, (defDisc * (baseNeedNoIn + fee)) / baseGain);
        }

        const steps = (0.75 * Lq) / Math.max(1, this.cnt[q]);
        if (this.cnt[q] < 25 && steps > P.contactStepsMax && !nearCollapse && !onMe) {
          c *= 1 + P.contactPenalty * Math.min(400, steps - P.contactStepsMax);
        }

        if (allyAtk > 0) {
          const jointNeed = Math.max(1, rawNeed - Math.floor(0.85 * allyAtk));
          c = (jointNeed + fee) / baseGain;
        }
        let jointStrike = false;
        if (P.enableCoordinatedStrike > 0 && P.p4JointStrike > 0 && g.teams && g.teams[me] > 0) {
          const jNeed = this.p4JointNeed(g, q, rawNeed);
          if (jNeed > 0 && jNeed < rawNeed) {
            c = Math.min(c, (jNeed + fee) / baseGain);
            jointStrike = true;
            this.vCount("p4_joint_offer");
          }
        }
        let squadWarTeams = 0, qTeamEngaged = false;
        if (g.teams && g.teams[me] > 0) {
          const engagedTeams = new Set();
          for (let p = 0; p < g.humans; p++) {
            if (!g.alive[p] || (!this.isTeammate(g, p) && !this.isOurSquadBot(g, p))) continue;
            const sbP = g.slotBase(p);
            for (let i = 0; i < g.atkCount[p]; i++) {
              const tId = g.atkTarget[sbP + i];
              if (tId >= 0 && tId < g.humans && !g.isBot(tId) && !this.isTeammate(g, tId)) engagedTeams.add(g.teams[tId]);
            }
          }
          squadWarTeams = engagedTeams.size;
          qTeamEngaged = engagedTeams.has(g.teams[q]);
        }
        let rankMult = 1.0;
        if (randomTeamAtk > 0) { c *= 0.68; rankMult *= 0.60; }
        if (atkOnBoss > 0 || bossAtkOnQ > 0) {
          c *= 0.65;
          rankMult *= 0.58;
        } else if (clanAllyAtkers >= 2 || allyAtk >= 0.15 * Bq) {
          c *= 0.58;
          rankMult *= 0.50;
        } else if (clanAllyAtkers > 0 || allyAtk > 0.04 * Bq) {
          c *= 0.68;
          rankMult *= 0.62;
        } else if (atkOnAlly > 0.06 * Bq) {
          c *= 0.75;
          rankMult *= 0.70;
        } else if (squadWarTeams >= 1 && !qTeamEngaged && !onMe && !nearCollapse) {
          c *= 1.45;
          rankMult *= 1.45;
        }
        if (
          (P.aggMemMode === 2 ||
            (P.aggMemMode === 8 && g.t >= 4500 && !bleeding && !nearCollapse && nHumans <= 20)) &&
          q === aggQ &&
          !nearCollapse &&
          !isStaleHardAgg
        ) {
          rankMult *= 0.82;
        }
        if (q === focusQ && !nearCollapse) {
          const inRankWindow =
            (P.focusRankOnly === 1 && B <= 100 * L && g.t < 3800) ||
            (P.focusRankOnly === 2 && B <= 100 * L && g.t >= 2950 && g.t < 3800);
          if (inRankWindow) {
            rankMult *= P.focusBonus;
          } else {
            c *= P.focusBonus;
          }
        }

        const newNbs = nHumans >= 3 ? this.newHumansExposed(g, q) : 0;
        if (g.t < 2500 && nHumans >= 4) {
          if (newNbs === 0) c *= P.pocket0Mult;
          else if (newNbs === 1) c *= P.pocket1Rank;
        }
        if (P.latePocketMode > 0 && g.t >= 3500 && nHumans >= 5 && humanNbs.length >= 3 && !nearCollapse && !bleeding && !onMe) {
          if (newNbs === 0) rankMult *= 0.85;
          else if (newNbs >= 2) rankMult *= 1.18;
        }

        if (g.t >= 2500 && nHumans >= 3 && humanNbs.length === 1 && !nearCollapse && !bleeding && !onMe && newNbs > 0) {
          c *= P.soleBufferPenalty;
        }

        if (q === topRival && g.t >= 3500 && g.terr[me] + Lq >= P.topRivalMinShare * g.land && B >= 0.70 * Bq && (this.cnt[q] ?? 0) >= 35 && !nearCollapse) {
          if (q === focusQ) {
            c *= P.topRivalFocusMult;
          } else if (nHumans <= 3 && !onMe) {
            c *= P.topRival3Mult;
          } else if (P.topRivalStrikeMult < 1 && B >= 1.10 * Bq && !onMe) {
            c *= P.topRivalStrikeMult;
          }
        }

        const shadowedByTop = P.leaderHardFrom > 0 && !this.isNoFullSend && g.t >= P.leaderHardFrom && topRival >= 0 && g.terr[topRival] > L && g.bal[topRival] > B;
        const isGiantTopRival = P.a06AloneSafe > 0 && !this.isNoFullSend && q === topRival && g.t >= 4800 && Bq > 1.15 * B && dq >= 120 && rawNeed > 1.5 * B;
        const isLeaderFortress =
          P.leaderHardFrom > 0 &&
          !this.isNoFullSend &&
          g.t >= P.leaderHardFrom &&
          L >= P.leaderMinShare * g.land &&
          nHumans >= 5 &&
          dq >= 0.90 * dMe &&
          (Bq >= 0.30 * B || dq >= 120) &&
          rawNeed > 0.45 * B;
        const baseHard =
          q !== focusQ &&
          !nearCollapse &&
          !bleeding &&
          !onMe &&
          ((q !== topRival && ((dq > 1.08 * dMe && Bq >= 0.70 * B) || (shadowedByTop && dq >= 110 && Bq >= 0.55 * B))) ||
            isLeaderFortress || isGiantTopRival);
        const stageMatch =
          P.guardMode === 1
            ? nHumans >= 5 && g.terr[me] + Lq < 0.50 * g.land
            : P.guardMode === 2
              ? nHumans <= 5 || g.terr[me] + Lq >= 0.50 * g.land
              : P.guardMode === 3;
        const isCrowdedHard = baseHard && stageMatch;
        if (isCrowdedHard && P.crowdedHardPenalty > 1) {
          c *= P.crowdedHardPenalty;
        }

        const pulseMode =
          nearCollapse ||
          bleeding ||
          ((tD < P.thinMaxTD || rawNeed > 0.30 * B) && !(g.t < 2400 && !onMe && rawNeed > 0.35 * B));
        out.push({
          q,
          person: true,
          tD,
          need: rawNeed,
          c,
          rankC: c * rankMult,
          pulseMode,
          nearCollapse,
          bleeding,
          onMe,
          inAtk,
          newNbs,
          isCrowdedHard,
          isAgg: q === aggQ,
          jointStrike,
        });
      }
    }

    if (P.seaCore > 0 && g.t >= 1000) {
      for (const dh of doorHarvestCandidates(g, me, this.seaState, {
        maxBoats: 5,
        atkFreshBoats: P.atkFreshBoats > 0,
        baseRatePer10: P.seaRebateMode > 0 ? this.baseRate(g) : 0,
      })) {
        if (g.terr[dh.q] < 1200) continue;
        out.push({
          q: dh.q,
          person: true,
          isDoorSea: true,
          doorInfo: dh,
          tD: dh.tD,
          need: dh.boatTroops * (dh.spots?.length ?? 1),
          c: dh.c,
          rankC: dh.c,
          pulseMode: true,
          nearCollapse: dh.nearCollapse,
          bleeding: true,
          onMe: false,
          inAtk: 0,
        });
      }
    }

    return out.sort((a, b) => (a.rankC ?? a.c) - (b.rankC ?? b.c));
  }

  buyLand(g) {
    const P = this.p, me = this.me;
    const B = g.bal[me], L = Math.max(1, g.terr[me]), fee = iV(12 * B, 1024);
    const dMe = B / L;
    const dMedOther = this.otherHumanMedDens(g);
    const nHumans = this.livingHumanCount(g);
    const humanNbCount = this.nb.filter((p) => g.alive[p] && this.person(g, p)).length;

    const m = P.maxW * this.winRatio(g.t);
    const refDens = dMedOther !== null && g.t >= P.marketFrom ? Math.max(dMe, P.marketFloor * dMedOther) : dMe;
    const worth = m * refDens;
    const over = P.surplus > 0 && B > 100 * L;
    const cheap = P.growth > 0 ? 0.1 / this.baseRate(g) : 0;

    for (const o of this.offers(g)) {
      const { q, c, need, person } = o;
      this.vKeepNext = null;

      if (c >= worth && c >= cheap && !over) break;
      // v28/P1 arbitration pass (see actCore): only land worth its price, or an attacker to answer
      if (this.buyQuality && !(c < worth || o.onMe)) continue;

      const isSoleHealthyBuffer =
        person && !o.isDoorSea && nHumans >= 3 && !o.nearCollapse && !o.bleeding && !o.onMe && o.newNbs > 0 && humanNbCount === 1;
      const soleCapMult = P.enableSmartOverCap > 0 && P.p5SoleBufferUnlock > 0 && (!this.p5HasOpenDonateTarget(g) || g.bal[q] <= 0.90 * B)
        ? P.p5SoleCapUnlocked
        : P.overHumanCap;
      if (isSoleHealthyBuffer && c >= worth && c >= cheap && B < soleCapMult * 100 * L) {
        continue;
      }
      if (isSoleHealthyBuffer && soleCapMult < P.overHumanCap && B >= soleCapMult * 100 * L && B < P.overHumanCap * 100 * L) {
        this.vCount("p5_sole_unlock");
      }

      if (
        P.enableSmartOverCap > 0 &&
        P.p5SmartOver > 0 &&
        over &&
        person &&
        !o.isDoorSea &&
        !o.nearCollapse &&
        !o.bleeding &&
        !o.onMe &&
        !o.jointStrike &&
        c >= worth &&
        c >= cheap &&
        dMe < 138
      ) {
        const dqO = g.bal[q] / Math.max(1, g.terr[q]);
        if (g.bal[q] >= P.p5HeavyBalK * B || (dqO >= P.p5HeavyDensK * dMe && g.bal[q] >= 0.85 * B)) {
          this.vCount("p5_heavy_veto");
          continue;
        }
      }

      if (person && !o.isDoorSea && g.terr[q] < 250 && fee > 2 * need && c > 8 * worth && nHumans >= 3) {
        continue;
      }

      const hardCapMult = P.crowdedHardCap;
      if (person && !o.isDoorSea && o.isCrowdedHard && c >= worth && c >= cheap && B < hardCapMult * 100 * L) {
        continue;
      }

      if (P.absorbMode >= 1 && person && !o.isDoorSea && !o.nearCollapse && (o.inAtk ?? 0) >= P.absorbWaveMin * B) {
        continue;
      }

      if (o.isDoorSea) {
        const dh = o.doorInfo;
        const spots = dh.spots?.length ? dh.spots : [{ d: dh.d, waterPix: dh.water, dir: dh.dir, landPix: dh.landing }];
        const safe = Math.min(this.safeAt(g, -1), P.oppFloorCap * L);
        const combinedFee = iV((32 * spots.length + 12) * B, 1024);
        if (B - combinedFee - dh.boatTroops * spots.length < safe || dh.c >= 0.90 * worth) continue;
        let launched = 0;
        for (const sp of spots) {
          const curB = g.bal[me];
          if (curB < 200 || g.boatCount[me] >= 5) break;
          const sendTr = Math.max(30, dh.boatTroops);
          const pct = Math.max(0, Math.min(1023, Math.ceil((sendTr * 1024) / curB) - 1));
          const ok = g.boatTo ? this.xBoatTo(g, pct, sp.landPix, 12, 'doorHarvest') : this.xBoat(g, pct, sp.waterPix, sp.dir, 'doorHarvest');
          if (ok) {
            this.seaState.stats.door_harvest.boats++;
            this.seaState.stats.door_harvest.fee += iV(32 * curB, 1024);
            this.seaState.stats.door_harvest.troops += sendTr;
            this.boats++;
            launched++;
          }
        }
        if (launched > 0) {
          this.seaState.pendingHandoffs.set(q, {
            expireTick: g.t + 90,
            initialCnt: 0,
            landings: spots.slice(0, launched).map((s) => s.landPix),
            wantTroops: Math.floor(P.pulseFrac * g.bal[me]),
          });
          this.cmds++;
          return true;
        }
        continue;
      }

      let safe = this.safeAt(g, q);
      if (!person || o.nearCollapse || (P.bleedSafeCap > 0 && (o.bleeding || o.tD < 0.45))) {
        const capPerPx = person && o.nearCollapse && (o.inAtk ?? 0) < 0.02 * B && ((c < 0.25 * worth && need <= 0.10 * B) || (g.bal[q] <= 0.05 * B && c < 25)) ? Math.min(P.oppFloorCap, P.collapseFloorCap ?? 85) : P.oppFloorCap;
        safe = Math.min(safe, capPerPx * L);
      }
      // v28/P3: the land of a bot, of a seat that left or of a remnant may be bought from below the
      // people floor and the bot floor (see p3Floor)
      let safeWas = -1;
      if (P.enableAiFloorCap > 0 && P.p3Decouple > 0 && this.p3Prey(g, q, need)) {
        const r = this.p3Floor(g, safe);
        if (r < safe) {
          safeWas = safe;
          safe = r;
        }
      }

      let keep = Infinity;
      if (c < cheap) keep = 0;
      if (c < worth) {
        const worthOwn = P.ownWorthMinKeep > 0 && g.t >= P.ownWorthFrom && !o.nearCollapse ? m * dMe : worth;
        const budget = Math.max(0, (worthOwn * L - fee * m - c * L) / (1 + m));
        const minKeep = person && (o.nearCollapse || (P.bleedDiscount < 1 && o.bleeding) || (P.thinDiscount < 1 && o.tD < P.thinMaxTD)) ? (0.70 * c * L) / m : (c * L) / m;
        keep = Math.min(keep, P.post > 0 ? Math.max(minKeep, B - fee - budget) : minKeep);
      }
      const isSiegeShrink =
        P.siegeShrinkRatio > 0 &&
        !this.isNoFullSend &&
        g.t >= P.leaderHardFrom &&
        L < P.siegeShrinkRatio * (g.peak?.[me] ?? L) &&
        nHumans >= 4 &&
        person &&
        !o.nearCollapse &&
        !o.bleeding;
      if (isSiegeShrink && c >= worth && c >= cheap && B < P.crowdedHardCap * 100 * L) {
        continue;
      }
      if (over) {
        const overKeepMult = dMe >= 122 ? 0.82 : isSoleHealthyBuffer ? P.overHumanKeep : P.hold;
        keep = Math.min(keep, overKeepMult * 100 * L);
      }
      // v28/P3: whether the relaxed floor is the one that binds (the floor of Vc is noted for the count in send)
      const p3Relaxed = safeWas >= 0 && Math.max(keep, safeWas) > Math.max(keep, safe);
      if (p3Relaxed) this.p3Old.set(q, { t: g.t, keep: Math.max(keep, safeWas) });
      keep = Math.max(keep, safe);

      const avail = B - fee - keep;
      if (avail <= 0) continue;
      this.vKeepNext = keep; // v28/P1: the floor every send on this offer is sized against

      if (!person) {
        const want = 1.25 * need + 3 * this.cnt[q];
        const x = Math.min(avail, want);
        if (x <= 0) continue;
        // (v28/P3: under the relaxed floor at most p3SpendFrac of the balance is free, which is
        // less than a chunk: a part of the bot's land is taken with a command of at least minCmd)
        if (x < want && x < P.chunk * B && !(p3Relaxed && x >= this.minCmd(g))) continue;
        return this.send(g, q, x);
      }

      // v28/P1 guardrail 2, the explicit first-strike kill budget: when 1.25 x need fits above dpKeep
      // (no person next to us, or next to the land we take, could collapse us with what is left) the
      // whole of it leaves in one command, never as a row of 12% pulses.
      if (P.enableInflightLedger > 0 && P.p1KillBudget > 0 && !this.isNoFullSend && (c < worth || o.onMe)) {
        const wantKill = 1.25 * need + 3 * this.cnt[q];
        const keepKill = Math.max(keep, this.dpKeep(g), this.killKeep(g, 1, this.peopleOf(g, q)));
        if (wantKill >= this.minCmd(g) && wantKill <= 0.38 * B && wantKill + fee <= B - keepKill) {
          this.vCount("p1_kill_budget");
          this.vKeepNext = keepKill;
          return this.send(g, q, wantKill);
        }
      }

      const usePulseBlock =
        P.pulseFrac > 0 && (!over || o.nearCollapse || o.bleeding || need > 0.30 * B || avail < P.chunk * B);
      const inAtk = o.inAtk ?? 0;
      const curAtk = g.attackTroopsOn(me, q) + this.inflightOn(g, q);
      const blockUndersized = (amt) => {
        if (P.counterClearMode === 6) return false;
        if (!(P.counterClearMode >= 1) || o.nearCollapse || !(inAtk > 0) || !(curAtk + amt <= 1.05 * inAtk)) return false;
        if (P.counterClearMode >= 3 && o.bleeding) return false;
        if (P.counterClearMode >= 4 && g.t < 3500) return false;
        return true;
      };

      // Helper for Combo 2 (#2470): For narrow-front land neighbours (`cnt[q] < 18`), launch 1-2 minimal
      // coastal bridgehead boats FIRST, wait 2 ticks after landing until they turn into `P_BORDER`, then fire `g.attack`!
      const tryNarrowBoatFirst = (wantLandTroops) => {
        if (
          !(P.narrowBoatFirstMode > 0) ||
          !(P.seaCore > 0) ||
          o.nearCollapse ||
          o.onMe ||
          inAtk > 0 ||
          curAtk > 0 ||
          g.hasAttack(me, q) ||
          this.seaState.pendingHandoffs.has(q) ||
          (this.cnt[q] ?? 0) >= 18 ||
          g.terr[q] < 5000 ||
          !g.boatsAllowed ||
          !g.boatsAllowed(me) ||
          g.boatCount[me] >= 5
        ) {
          return false;
        }
        const oneBoatFee = iV(32 * B, 1024);
        if (oneBoatFee > 0.14 * wantLandTroops) return false;
        const spots = findCoastalBridgeheads(g, me, this.seaState, q, {
          maxWaterDist: 18,
          maxSpots: Math.min(2, 5 - g.boatCount[me]),
          minSpacing: 22,
        });
        if (!spots.length) return false;
        let launched = 0;
        const landedList = [];
        for (const sp of spots) {
          const curB = g.bal[me];
          if (curB < 500 || iV(32 * curB, 1024) > 0.14 * wantLandTroops) break;
          const sendTr = Math.max(60, Math.ceil(6 * Math.exp(P.boatDecay * sp.d)));
          const pct = Math.max(0, Math.min(1023, Math.ceil((sendTr * 1024) / curB) - 1));
          const ok = g.boatTo ? this.xBoatTo(g, pct, sp.landPix, 12, 'narrowBoatFirst') : this.xBoat(g, pct, sp.waterPix, sp.dir, 'narrowBoatFirst');
          if (ok) {
            this.seaState.widenLandings ??= new Map();
            const wl = this.seaState.widenLandings.get(q) ?? [];
            wl.push(sp.landPix);
            this.seaState.widenLandings.set(q, wl);
            this.seaState.widenCount.set(q, (this.seaState.widenCount.get(q) ?? 0) + 1);
            this.seaState.stats.widen.boats++;
            this.seaState.stats.widen.fee += iV(32 * curB, 1024);
            this.boats++;
            landedList.push(sp.landPix);
            launched++;
          }
        }
        if (launched > 0) {
          this.seaState.pendingHandoffs.set(q, {
            expireTick: g.t + 75,
            initialCnt: this.cnt[q] ?? 0,
            landings: landedList,
            wantTroops: wantLandTroops,
          });
          this.cmds++;
          return true;
        }
        return false;
      };

      if (usePulseBlock) {
        // Combo 3 (#1): Use `attack(0)` exact 1-ring draw ONLY for non-kill probing (`1.20 * need > capFrac`),
        // where sending `12%` would only take 1-2 rings and burn its leftover tail troops on the next ring!
        // When `1.20 * need <= capFrac` (target is weak enough to be conquered across multiple rings in one go),
        // send the full multi-ring amount `x`!
        const cntQ = Math.max(1, this.cnt[q] ?? 1);
        const ring1Def = iV(cntQ * g.bal[q], 1 + iV(10 * g.terr[q], 16));
        const ring1Cost = cntQ * 2 + 2 * ring1Def + inAtk + 1;
        const recentHit = g.t - (this.hitTo.get(q) ?? -999) < 12;
        const canZeroPulse = (amt) =>
          P.zeroPulseMode > 0 &&
          !o.nearCollapse &&
          (!o.bleeding || P.exactRingMode >= 2) &&
          inAtk === 0 &&
          curAtk === 0 &&
          !g.hasAttack(me, q) &&
          !recentHit &&
          cntQ >= 18 &&
          1.20 * need > amt &&
          ring1Cost >= 2.5 * fee &&
          ring1Cost <= avail &&
          amt < 1.85 * ring1Cost;

        // Multi-ring exact alignment (`exactRingMode`): when `amt >= 1.85 * ring1Cost` and `1.20 * need > amt`,
        // trim `amt` to the exact cost of `K` full rings + `2 * cntQ` so the `(K+1)`-th ring tail is returned to `bal[me]`!
        const alignMultiRing = (amt) => {
          if (!(P.exactRingMode > 0) || o.nearCollapse || curAtk > 0 || 1.20 * need <= amt || cntQ < 16) return amt;
          let remB = g.bal[q], remL = g.terr[q], total = 0, rings = 0;
          for (let r = 0; r < 6; r++) {
            const def = iV(cntQ * remB, 1 + iV(10 * remL, 16));
            const cost = cntQ * 2 + 2 * def + (r === 0 ? inAtk : 0);
            if (total + cost + cntQ > amt) break;
            total += cost;
            rings++;
            remB = Math.max(0, remB - def);
            remL = Math.max(1, remL - cntQ);
          }
          if (rings >= 1 && amt - total > 2.5 * cntQ) {
            const trimmed = total + 2 * cntQ;
            if (trimmed >= Math.max(this.minCmd(g), P.pulseMinShare * B)) return trimmed;
          }
          return amt;
        };
        const capNarrow = (amt) => {
          if (!(P.enableCoordinatedStrike > 0 && P.p4NarrowCap > 0) || o.nearCollapse || inAtk > 0 || cntQ >= P.p4NarrowCnt) return amt;
          const cap = Math.max(this.minCmd(g), P.p4NarrowRings * ring1Cost);
          if (amt > cap) {
            this.vCount("p4_narrow_cap");
            return cap;
          }
          return amt;
        };

        if (g.t >= 3800 && (o.nearCollapse || o.bleeding || (P.aggMemMode === 2 && o.isAgg))) {
          if (curAtk >= 0.08 * B || curAtk >= 0.65 * need) continue;
          const targetSlot = Math.min(0.85 * need + 3 * this.cnt[q], Math.floor(P.pulseFrac * B));
          let pulse = Math.min(avail, Math.max(targetSlot - curAtk, Math.floor(0.08 * B)));
          if (P.counterClearMode === 2 && !o.nearCollapse && inAtk > 0 && curAtk + pulse <= 1.05 * inAtk) {
            pulse = Math.min(avail, Math.min(Math.floor(0.28 * B), Math.ceil(1.05 * inAtk - curAtk + 0.05 * B)));
          }
          if (blockUndersized(pulse)) continue;
          pulse = capNarrow(alignMultiRing(pulse));
          if (pulse < Math.max(this.minCmd(g), P.pulseMinShare * B)) {
            const whole = this.p3Whole(g, o, avail, worth); // v28/P3 (0: skipped as in Vc)
            if (whole > 0) return this.send(g, q, whole);
            continue;
          }
          if (tryNarrowBoatFirst(pulse)) return true;
          return canZeroPulse(pulse) ? this.send(g, q, 1, pulse) : this.send(g, q, pulse);
        }

        if (o.nearCollapse) {
          if (curAtk >= 0.04 * B || curAtk >= 0.30 * need) continue;
          const pulse = Math.min(avail, Math.max(Math.floor(P.pulseFrac * B), Math.min(avail, Math.floor(0.30 * need))));
          if (pulse < Math.max(this.minCmd(g), P.pulseMinShare * B)) {
            const whole = this.p3Whole(g, o, avail, worth); // v28/P3 (0: skipped as in Vc)
            if (whole > 0) return this.send(g, q, whole);
            continue;
          }
          return this.send(g, q, pulse);
        }

        if (o.pulseMode) {
          if (curAtk >= 0.04 * B) continue;
          let capFrac = Math.floor(P.pulseFrac * B);
          if (P.counterClearMode === 2 && inAtk > 0) {
            capFrac = Math.max(capFrac, Math.min(Math.floor(0.28 * B), Math.ceil(1.05 * inAtk - curAtk + 0.05 * B)));
          }
          const want = Math.min(1.20 * need + 3 * this.cnt[q], capFrac);
          let x = Math.min(avail, want);
          if (blockUndersized(x)) continue;
          x = capNarrow(alignMultiRing(x));
          if (x < Math.max(this.minCmd(g), P.pulseMinShare * B)) {
            const whole = this.p3Whole(g, o, avail, worth); // v28/P3 (0: skipped as in Vc)
            if (whole > 0) return this.send(g, q, whole);
            continue;
          }
          if (tryNarrowBoatFirst(x)) return true;
          return canZeroPulse(x) ? this.send(g, q, 1, x) : this.send(g, q, x);
        }
      }

      const want = 1.25 * need + 3 * this.cnt[q];
      const x = Math.min(avail, want);
      if (x <= 0 || (x < want && (x < P.chunk * B || (P.pplKill > 0 && person)))) continue;
      if (person && blockUndersized(x)) continue;
      if (person && tryNarrowBoatFirst(x)) return true;
      return this.send(g, q, x);
    }
    return false;
  }

  boatFood(g) {
    const P = this.p, me = this.me;
    if (!(P.seaCore > 0)) return super.boatFood(g);
    if (this.neutral > 0 || g.t - (this.lastFood ?? -1e9) < P.boatEvery) return false;
    let activeHops = 0;
    if (this.seaState.inFlightIsles) {
      for (const [, expT] of this.seaState.inFlightIsles) if (g.t < expT) activeHops++;
    }
    if (!g.boatsAllowed(me) || g.boatCount[me] - activeHops >= P.maxBoats) return false;
    for (const q of this.nb) if (g.alive[q] && !this.person(g, q) && this.price(g, q) <= P.botMax) return false;
    this.lastFood = g.t;
    const hit = this.searchFood(g);
    if (!hit || hit.eff > P.botMax) return false;
    const bal = g.bal[me];
    const { floorAt } = this.floors(g);
    const floor = Math.max(this.reserve(g, hit.price), floorAt(hit.price));
    const max = P.boatFrac * (bal - floor);
    const min = Math.max(60, P.feeK * iV(32 * bal, 1024));
    if (max < min) return false;
    const fullAmount = Math.min(max, Math.max(P.foodK * hit.cost, min));

        const v = g.px[hit.land];
    if (!this.isMopUp(g) && v >= P_INNER) {
      const o = g.own[hit.land];
      // Exploit #15 (`t % 51 === 45` 60-px bot boat-interception blind spot):
      if (P.botPhaseMode > 0 && o >= 0 && g.isBot(o) && (45 - (g.t % 51) + 51) % 51 <= 6) {
        this.lastFood = g.t - P.boatEvery + P.period;
        return false;
      }
      if (this.nb.length > 0 && fullAmount > 600 && o >= 0 && o !== me && g.alive[o] && g.terr[o] >= 200 && !this.seaState.pendingHandoffs.has(o)) {
        const landCost = this.elimCost(g, o);
        const grow = Math.max(1.0, hit.cost / Math.max(1, landCost));
        const seaLoss = fullAmount * (1 - 1 / grow);
        const landFee = iV(12 * bal, 1024);
        if (seaLoss > landFee + 250) {
          const doDens = g.bal[o] / Math.max(1, g.terr[o]);
          const bridgeAmt =
            P.atkFreshBoats > 0 && g.attackTroopsOn(o, me) === 0 && !g.hasAttack(me, o)
              ? Math.min(fullAmount, Math.max(60, Math.ceil(6 * grow)))
              : Math.min(fullAmount, Math.max(60, Math.ceil((3 * (2 + 3.2 * doDens) + 25) * grow)));
          const pct = Math.max(0, Math.min(1023, Math.ceil((bridgeAmt * 1024) / bal) - 1));
          if (this.xBoatTo(g, pct, hit.land, undefined, 'boatFoodBridge')) {
            this.seaState.pendingHandoffs.set(o, {
              expireTick: g.t + 160,
              initialCnt: 0,
              landings: [hit.land],
              wantTroops: Math.floor(fullAmount / grow),
            });
            this.boats++;
            this.cmds++;
            return true;
          }
        }
      }
    }

    const pct = Math.max(0, Math.min(1023, Math.ceil((fullAmount * 1024) / bal) - 1));
    if (!this.xBoatTo(g, pct, hit.land, undefined, 'boatFood')) return false;
    this.boats++;
    this.cmds++;
    return true;
  }

  searchFood(g) {
    if (this.isMopUp(g)) {
      const oldRange = this.p.boatRange;
      this.p.boatRange = 2500;
      const hit = super.searchFood(g);
      this.p.boatRange = oldRange;
      if (hit) hit.eff = Math.min(hit.eff, 2);
      return hit;
    }
    const hit = super.searchFood(g);
    if (!hit) return hit;
    if (this.p.enableSeaPrecision > 0 && this.p.p7SailDecay > 0 && (hit.dist ?? 0) > 25) {
      hit.eff *= Math.exp(0.0035 * (hit.dist - 25));
      this.vCount("p7_sail_decay");
    }
    if (!(this.p.foodRebate > 0)) return hit;
    const me = this.me, B = g.bal[me], L = Math.max(1, g.terr[me]);
    if (B > 100 * L) {
      const estTicks = 80;
      const rebate = futureInterestRebate(g, me, Math.min(hit.cost, 0.28 * B), estTicks, this.baseRate(g));
      if (rebate > 0) {
        const gain = Math.max(1, (hit.cost + iV(32 * B, 1024)) / Math.max(1, hit.eff));
        hit.eff = Math.max(2, hit.eff - rebate / gain);
      }
    }
    return hit;
  }

  // ==========================================================================================
  // v28 infrastructure: counters, log, clock, host reads shared by the modules
  // ==========================================================================================

  vCount(k, n = 1) {
    this.v28n[k] = (this.v28n[k] || 0) + n;
  }

  vLog(tag, g, msg) {
    if (typeof window !== "undefined" && window.__hlLog) window.__hlLog(`[V28-${tag}] t=${g.t} me=${this.me} ${msg}`);
  }

  // Wall clock in ms. A harness sets window.__c136Now to its simulated time.
  vNow() {
    if (typeof window !== "undefined" && typeof window.__c136Now === "function") return window.__c136Now();
    return typeof performance !== "undefined" ? performance.now() : Date.now();
  }

  // A person who left the game: the game runs the seat as a bot from then on (state 2 in the
  // simulator; in the live page the bridge keeps window.__quitPlayers, and the player state array of
  // the page is read through window.dictionary when it is there).
  vShell(g, p) {
    if (p >= g.humans) return false;
    if (g.state && ArrayBuffer.isView(g.state) && g.state.length >= g.humans) return g.state[p] === 2;
    if (typeof window === "undefined") return false;
    if (window.__quitPlayers && window.__quitPlayers.has(p)) return true;
    try {
      const d = window.dictionary, pd = d && d.playerData && window[d.playerData];
      const st = pd && d.playerStates && pd[d.playerStates];
      if (st && st[p] === 2) return true;
    } catch {}
    return false;
  }

  // Room key: map size, land, seat count and a hash of all the people's names (two rooms on the same
  // map at the same time differ in their names).
  vRoomKey(g) {
    let h = 2166136261 >>> 0;
    for (let p = 0; p < g.humans; p++) {
      const s = String(g.names?.[p] ?? "");
      for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619) >>> 0;
      h = Math.imul(h ^ 0x2c, 16777619) >>> 0;
    }
    return `${g.W}x${g.H}_${g.land}_${g.humans}_${h.toString(36)}`;
  }

  // The ids of our seats in this room as the spawn coordinator placed them (spawn-coordinator-v28
  // puts `roster` and `roomKey` into every answer); null without one or when it is another room's.
  vRoster(g) {
    if (typeof window === "undefined") return null;
    const a = window.__c136Roster || window.__tsbAssignedSpawn;
    if (!a || !Array.isArray(a.roster) || !a.roster.length) return null;
    if (a.roomKey && a.roomKey !== this.vRoomKey(g)) return null;
    return a.roster;
  }

  // Every tick, before anything else: what the modules watch between decisions.
  vTick(g) {
    const P = this.p;
    if (P.enableCollapseGuard > 0) this.peakTick(g);
    if (P.enableInflightLedger > 0) this.ledgerObserve(g);
    if (P.enableQuotaExactDonate > 0) this.p6QuotaTick(g);
    if (P.enableSeaPrecision > 0) this.p7BoxedTick(g);
  }

  // ==========================================================================================
  // v28/P4, P5, P6, P7 helpers
  // ==========================================================================================

  p4JointNeed(g, q, rawNeed) {
    const P = this.p, me = this.me, L = Math.max(1, g.terr[me]);
    const mySafe = Math.min(this.safeAt(g, q), P.oppFloorCap * L);
    const myAvail = Math.max(0, g.bal[me] - mySafe) + g.attackTroopsOn(me, q) + this.inflightOn(g, q);
    if (!(myAvail > 0)) return 0;
    const activeEngagement = g.attackTroopsOn(q, me) > 0 || g.attackTroopsOn(me, q) > 0;
    const roster = this.vRoster(g);
    let sumAvail = myAvail, allies = 1, anyAllyEngaged = activeEngagement;
    const B = g.border[q], px = g.px, own = g.own, d = g.dir4;
    const n = B.length, step = n > 512 ? Math.ceil(n / 512) : 1;
    const seen = this.oseen, st = ++this.ostamp;
    for (let i = n - 1; i >= 0; i -= step) {
      const b = B[i];
      for (let k = 0; k < 4; k++) {
        const c = b + d[k];
        if (px[c] < P_INNER) continue;
        const a = own[c];
        if (a === q || a === me || seen[a] === st) continue;
        seen[a] = st;
        if (!g.alive[a] || g.isBot(a) || this.vShell(g, a) || !this.isTeammate(g, a)) continue;
        if (roster ? !roster.includes(a) : !this.isSquadName(g, a)) continue;
        if (g.attackTroopsOn(a, q) > 0 || g.attackTroopsOn(q, a) > 0) anyAllyEngaged = true;
        const aAvail = Math.max(0, g.bal[a] - 68 * g.terr[a]) + g.attackTroopsOn(a, q);
        if (aAvail > 0) {
          sumAvail += aAvail;
          allies++;
        }
      }
    }
    if (allies < 2 || (!anyAllyEngaged && g.t < 2400) || sumAvail < P.p4JointK * rawNeed) return 0;
    const share = Math.max(P.p4MinShare, myAvail / Math.max(1, sumAvail));
    return Math.max(1, Math.floor(rawNeed * share));
  }

  p5HasOpenDonateTarget(g) {
    const me = this.me;
    if (!g.teams || !(g.teams[me] > 0) || g.t < 1500) return false;
    for (let p = 0; p < g.humans; p++) {
      if (p === me || !g.alive[p] || !this.isTeammate(g, p) || this.vShell(g, p)) continue;
      if (!this.isOurSquadBot(g, p) && !this.isBossNpl(g, p)) continue;
      if (g.terr[p] < 1200) continue;
      const dAlly = g.bal[p] / Math.max(1, g.terr[p]);
      if (dAlly < 90) return true;
    }
    return false;
  }

  p6RoomState(g) {
    Policy._rooms ??= new Map();
    const k = `${g.W}x${g.H}_${g.humans}`;
    let st = Policy._rooms.get(k);
    if (!st || g.t < st.lastT) {
      st = { lastT: g.t, donFlows: [], donQuotaUsed: new Map(), boatClaims: new Map() };
      Policy._rooms.set(k, st);
    }
    st.lastT = g.t;
    return st;
  }

  p6QuotaTick() {}

  p6DonCap(g) {
    if (typeof g.donCap === "number") return g.donCap;
    let cap = 15;
    for (let k = 99; k <= g.t; k += 100) {
      cap += k < 1071 ? 4 : k < 2142 ? 6 : k < 3213 ? 8 : 10;
    }
    return cap;
  }

  p6DonCost(g, q, v, atT = g.t) {
    if (atT >= 4284 || g.isBot(q)) return 0;
    if (atT >= 3213) {
      const sc = Math.max(1, Math.min(100 * g.terr[q], 1e9));
      return 4 + iV(100 * v, sc);
    }
    const uw = 1 + iV(g.land, 300);
    const mult = atT < 357 ? 1 : atT < 714 ? 4 : atT < 1071 ? 10 : atT < 2142 ? 30 : 100;
    return 2 + iV(100 * v, mult * uw);
  }

  p6MaxQuotaTroops(g, q) {
    const landT = g.t + (g.online ? 8 : 0);
    if (landT >= 4284 || g.isBot(q)) return Infinity;
    const st = this.p6RoomState(g);
    let used = typeof g.donQuota?.[q] === "number" ? g.donQuota[q] : (st.donQuotaUsed.get(q) ?? 0);
    if (g.online) {
      for (let i = st.donFlows.length - 1; i >= 0; i--) {
        const f = st.donFlows[i];
        if (g.t - f.t > 16) break;
        if (f.to === q) used += f.cost;
      }
    }
    const remPts = this.p6DonCap(g) - used;
    if (landT >= 3213) {
      if (remPts < 4) return 0;
      const sc = Math.max(1, Math.min(100 * g.terr[q], 1e9));
      return Math.max(0, Math.floor(0.90 * (((remPts - 4 + 1) * sc - 1) / 100)));
    }
    if (remPts < 2) return 0;
    const uw = 1 + iV(g.land, 300);
    const mult = landT < 357 ? 1 : landT < 714 ? 4 : landT < 1071 ? 10 : landT < 2142 ? 30 : 100;
    const denom = mult * uw;
    return Math.max(0, Math.floor(0.90 * (((remPts - 2 + 1) * denom - 1) / 100)));
  }

  p6IsPingPong(g, target) {
    const P = this.p, me = this.me, t = g.t;
    const st = this.p6RoomState(g);
    for (let i = st.donFlows.length - 1; i >= 0; i--) {
      const f = st.donFlows[i];
      if (t - f.t > P.p6PingPongWin) break;
      if (f.from === target && f.to === me) return true;
      if (f.to === me && t - f.t <= P.p6RelayWin) return true;
    }
    return false;
  }

  p6InflightTo(g, target) {
    if (!g.online) return 0;
    const st = this.p6RoomState(g);
    let s = 0;
    for (let i = st.donFlows.length - 1; i >= 0; i--) {
      const f = st.donFlows[i];
      if (g.t - f.t > 18) break;
      if (f.to === target) s += f.amt;
    }
    return s;
  }

  p6RecordDonate(g, target, amt) {
    const st = this.p6RoomState(g);
    const cost = this.p6DonCost(g, target, amt, g.t + (g.online ? 8 : 0));
    st.donQuotaUsed.set(target, (st.donQuotaUsed.get(target) ?? 0) + cost);
    st.donFlows.push({ from: this.me, to: target, t: g.t, amt: Math.round(amt * 0.9375), cost });
    if (st.donFlows.length > 128) st.donFlows.splice(0, st.donFlows.length - 128);
  }

  p7BoxedTick(g) {
    if (this.nb.length === 0 && this.neutral === 0) {
      if (this.boxedSinceT < 0) this.boxedSinceT = g.t;
    } else {
      this.boxedSinceT = -1;
    }
  }

  p7BoatVeto(g, pct, land, site) {
    const P = this.p;
    if (!(P.enableSeaPrecision > 0)) return false;
    const isBridgehead = site === "narrowBoatFirst" || site === "sendWiden" || site === "widenFront" || site === "doorHarvest" || site === "boatFoodBridge" || site === "frogHop";
    if (P.p7MinPayloadFee > 0 && g.t >= 600 && !isBridgehead && !this.isMopUp(g)) {
      const minPct = Math.round(32 * P.p7MinFeeK) - 1;
      if (pct < minPct) {
        this.vCount("p7_min_fee_veto");
        return true;
      }
    }
    if (P.p7IsleDedup > 0 && land >= 0 && !isBridgehead && g.teams && g.teams[this.me] > 0) {
      const st = this.p6RoomState(g);
      const rx = Math.floor((land % g.W) / 18), ry = Math.floor(Math.floor(land / g.W) / 18);
      const rk = `${rx}_${ry}`;
      const prev = st.boatClaims.get(rk);
      if (prev && prev.by !== this.me && this.isTeammate(g, prev.by) && g.t - prev.t <= P.p7DedupWin) {
        this.vCount("p7_isle_dedup");
        return true;
      }
      st.boatClaims.set(rk, { by: this.me, t: g.t });
    }
    return false;
  }

  // ==========================================================================================
  // v28/P8: own collapse-line guard
  // ==========================================================================================

  vFault(g, name, e) {
    const n = (this.v28Faults[name] = (this.v28Faults[name] || 0) + 1);
    this.vCount("p8_fault");
    if (n <= 3 || n % 200 === 0) this.vLog("FAULT", g, `step=${name} n=${n} ${e && e.message} @ ${firstFrame(e)}`);
  }

  // Run one sub-step of act(); with P8 on, what it throws is logged and counted and the tick goes on.
  safeStep(g, name, fn) {
    const P = this.p;
    if (!(P.enableCollapseGuard > 0 && P.p8Isolate > 0)) return fn();
    try {
      return fn();
    } catch (e) {
      this.vFault(g, name, e);
      return false;
    }
  }

  // Our peak land as the game keeps it for the collapse test (aliveTick: it jumps up to our land at
  // once and falls by max(1, (peak - land) / 1000) a tick while we are below it); g.peak when the
  // host has it, else the copy kept here. Also the two land samples of the guard (see p8LossWin).
  peakTick(g) {
    const P = this.p, me = this.me, L = g.terr[me];
    const dt = this.peakT < 0 ? 1 : Math.max(1, Math.min(256, g.t - this.peakT));
    this.peakT = g.t;
    if (!(this.peakSeen > L)) this.peakSeen = L;
    else for (let i = 0; i < dt && this.peakSeen > L; i++) this.peakSeen -= Math.max(1, iV(this.peakSeen - L, 1000));
    if (g.t - this.lgSampleT >= P.p8LossWin) {
      this.lgTerrOld = this.lgSampleT < 0 ? L : this.lgTerrNew;
      this.lgTerrNew = L;
      this.lgSampleT = g.t;
    }
  }

  myPeak(g) {
    const pk = g.peak ? g.peak[this.me] : 0;
    return pk > 0 ? pk : Math.max(this.peakSeen, g.terr[this.me]);
  }

  // Null, or what the guard needs when we are within p8Margin x peak of our collapse line and are
  // losing land to an attack.
  lifeGuardState(g) {
    const P = this.p, me = this.me, L = g.terr[me];
    const peak = this.myPeak(g), line = iV(peak, 4), margin = L - line;
    if (!(margin < P.p8Margin * peak)) return null;
    if (!(L < Math.max(this.lgTerrOld, this.lgTerrNew))) return null;
    let inc = 0, main = -1, mainTr = 0;
    for (const a of g.attackersOf(me)) {
      if (a === me || this.isTeammate(g, a)) continue;
      const tr = g.attackTroopsOn(a, me);
      inc += tr;
      if (tr > mainTr) {
        mainTr = tr;
        main = a;
      }
    }
    if (!(inc > 0)) return null;
    return { L, peak, line, margin, inc, main, mainTr };
  }

  // One command of the guard (true when sent): the price gate and the dpKeep freeze do not apply
  // here, only p8KeepFrac of the balance stays home. In turn: a counter on the main attacker (our
  // troops cancel its troops on us one for one before any land changes hands), then land: neutral
  // land first, else the cheapest neighbour per pixel that is a bot, a seat that left, or a weak person.
  lifeGuardAct(g) {
    const P = this.p, me = this.me;
    if (!(P.enableCollapseGuard > 0 && P.p8LifeGuard > 0)) return false;
    const st = this.lifeGuardState(g);
    if (!st) {
      if (this.lgOn) this.vLog("LIFEGUARD", g, `leave L=${g.terr[me]} peak=${this.myPeak(g)}`);
      this.lgOn = false;
      return false;
    }
    if (!this.lgOn) {
      this.lgOn = true;
      this.vCount("p8_guard_enter");
      this.vLog("LIFEGUARD", g, `enter L=${st.L} peak=${st.peak} line=${st.line} margin=${st.margin} inc=${st.inc} main=${st.main}`);
    }
    this.vCount("p8_guard_tick");
    const B = g.bal[me], fee = iV(12 * B, 1024), min = this.minCmd(g);
    const avail = B - fee - P.p8KeepFrac * B;
    if (avail < min) return false;

    const tryCounter = () => {
      const q = st.main;
      if (q < 0 || q === NEUTRAL || !(st.mainTr >= P.p8CounterMin * B)) return false;
      if (!g.hasAttack(me, q) && !g.hasFreeSlot(me)) return false;
      const x = Math.min(avail, P.p8CounterFrac * B, 1.05 * st.mainTr - g.attackTroopsOn(me, q) - this.inflightOn(g, q));
      if (!(x >= min) || !this.send(g, q, x)) return false;
      this.vCount("p8_guard_counter");
      this.vLog("LIFEGUARD", g, `counter q=${q} x=${Math.round(x)} inc=${st.mainTr} margin=${st.margin}`);
      return true;
    };
    const tryLand = () => {
      const needPx = Math.ceil(P.p8Margin * st.peak - st.margin) + 8;
      if (this.neutral > 0) {
        const x = Math.min(avail, P.p8PulseFrac * B, Math.max(min, 3 * Math.max(needPx, this.neutral)));
        if (x >= min && this.send(g, NEUTRAL, x)) {
          this.vCount("p8_guard_land");
          this.vLog("LIFEGUARD", g, `land neutral x=${Math.round(x)} margin=${st.margin}`);
          return true;
        }
      }
      let best = -1, bestPx = Infinity;
      for (const q of this.nb) {
        if (!g.alive[q] || !g.terr[q] || q === st.main) continue;
        if (!g.hasAttack(me, q) && !g.hasFreeSlot(me)) continue;
        if (this.person(g, q) && !this.vShell(g, q) && g.bal[q] > P.p8WeakRatio * B) continue;
        const px = this.price(g, q);
        if (px < bestPx) {
          bestPx = px;
          best = q;
        }
      }
      if (best < 0) return false;
      const x = Math.min(avail, P.p8PulseFrac * B, Math.max(min, bestPx * needPx + 3 * this.cnt[best]));
      if (!(x >= min) || !this.send(g, best, x)) return false;
      this.vCount("p8_guard_land");
      this.vLog("LIFEGUARD", g, `land q=${best} px=${bestPx.toFixed(1)} x=${Math.round(x)} margin=${st.margin}`);
      return true;
    };

    const first = this.lgLastKind === "counter" ? tryLand : tryCounter;
    const second = this.lgLastKind === "counter" ? tryCounter : tryLand;
    if (first()) {
      this.lgLastKind = first === tryCounter ? "counter" : "land";
      return true;
    }
    if (second()) {
      this.lgLastKind = second === tryCounter ? "counter" : "land";
      return true;
    }
    return false;
  }

  // ==========================================================================================
  // v28/P3: floors when buying the land of bots, of seats that left, of remnants
  //
  // Vc keeps two floors under every purchase: safeFinite (stay above the weakest other neighbour
  // of each bot next to us, so that the bot prefers it to us) and dpKeep (what the strongest
  // person next to us would need to collapse us). The first took a teammate or a seat that left
  // for "the other neighbour" and asked us to out-save it, whatever the bot itself could do; the
  // second froze the purchase of land that costs next to nothing. Here: the bot floor leaves those
  // neighbours out and is never more than the bot can send; and land of a bot, of a seat that left
  // or of a remnant may be bought with up to p3SpendFrac of the balance from below both floors,
  // p3KeepK x dpKeep staying home.
  // ==========================================================================================

  threatSkip(g, o) {
    const P = this.p;
    if (!(P.enableAiFloorCap > 0 && P.p3ThreatSkip > 0)) return false;
    return this.isTeammate(g, o) || this.isOurSquadBot(g, o) || this.vShell(g, o);
  }

  safeFinite(g, skip = -1) {
    const P = this.p;
    if (!(P.enableAiFloorCap > 0)) return super.safeFinite(g, skip);
    const me = this.me;
    let safe = 0, was = 0;
    for (const q of this.nb) {
      if (q === skip || g.alive[q] === 0 || !g.isBot(q) || !g.hasFreeSlot(q) || g.hasAttack(q, me)) continue;
      const th = this.threatOf(g, q);
      if (th.neutral) continue;
      const mine = g.attackTroopsOn(me, q);
      if (Number.isFinite(th.minAll)) was = Math.max(was, th.minAll - mine);
      if (!Number.isFinite(th.minOther)) continue;
      let v = th.minOther - mine;
      if (P.p3SafeCap > 0 && (g.terr[q] < 0.85 * g.terr[me] || g.bal[q] < 0.25 * g.bal[me])) {
        v = Math.min(v, P.p3ThetaAi * g.bal[q] + 2 * this.cnt[q]);
      }
      safe = Math.max(safe, v);
    }
    this.vCount("p3_sb_eval");
    if (safe < was) {
      this.vCount("p3_sb_lower");
      if (was > g.bal[me] && safe <= g.bal[me]) this.vCount("p3_sb_unlock");
    }
    return safe;
  }

  // Whether q's land is bought under the P3 rules: a bot, a seat that left, or a person with
  // next to no troops whose collapse costs a small part of our balance.
  p3Prey(g, q, need) {
    const P = this.p, B = g.bal[this.me];
    if (this.vShell(g, q)) return need < 0.18 * B;
    if (!this.person(g, q)) return g.bal[q] < 0.25 * B && need < 0.18 * B;
    return g.bal[q] < P.p3RemnantBal * B && need < P.p3RemnantNeed * B;
  }

  // The floor `guard` (people floor and bot floor) for such land.
  p3Floor(g, guard) {
    const P = this.p, B = g.bal[this.me];
    return Math.min(guard, Math.max((1 - P.p3SpendFrac) * B, P.p3KeepK * this.dpKeep(g)));
  }

  // Core, pulse paths: the troops to take offer o whole when the pulse sized for it is under the
  // least command (0: no). Only for land under p3CheapK x worth whose whole price fits above the floor.
  p3Whole(g, o, avail, worth) {
    const P = this.p;
    if (!(P.enableAiFloorCap > 0 && P.p3MinCmdFix > 0)) return 0;
    if (!(o.c < P.p3CheapK * worth) || !this.p3Prey(g, o.q, o.need)) return 0;
    const want = 1.25 * o.need + 3 * this.cnt[o.q];
    if (!(want <= avail)) return 0;
    this.vCount("p3_whole_core");
    return Math.min(avail, Math.max(want, this.minCmd(g)));
  }

  // Before the core (pickTarget): the same for a bot when less than the least command is left
  // above its floor.
  smallSend(g, q, avail, need, min) {
    const P = this.p, me = this.me;
    if (!(P.enableAiFloorCap > 0 && P.p3MinCmdFix > 0) || !(avail > 0)) return 0;
    if (this.person(g, q) && !this.vShell(g, q)) return 0;
    if (this.waitDump(g, q)) return 0;
    const want = P.foodK * need + 3 * this.cnt[q];
    if (!(want <= avail)) return 0;
    const left = iV(g.peak[q], 4);
    const share = Math.min(1, this.cnt[q] / Math.max(1, g.border[q].length));
    const c = (need + iV(12 * g.bal[me], 1024)) / Math.max(1, g.terr[q] - left + left * P.shareW * share);
    if (!(c < P.p3CheapK * this.winWorth(g))) return 0;
    this.vCount("p3_whole_early");
    return Math.min(avail, Math.max(want, min));
  }

  // ==========================================================================================
  // v28/P1: in-flight command ledger
  //
  // In the live game a command lands 10 to 20 ticks after it leaves (far longer in a stall), and
  // until then nothing we can read has changed: Vc decides again on the same balance and the same
  // need and sends the same thing again. The ledger keeps every command that has left and not
  // landed; the decisions count its troops as already on the way (inflightOn), and the exits below
  // let at most one command out per tick, hold back what the balance left after the commands in
  // flight cannot carry, and fall back to a short list of safe commands while the channel stalls.
  // A host that executes at once (the simulator) never has anything in flight.
  // ==========================================================================================

  xAttack(g, pct, target, site) {
    if (!(this.p.enableInflightLedger > 0)) return super.xAttack(g, pct, target, site);
    return this.ledgerSend(g, "attack", pct, target, site, (p) => super.xAttack(g, p, target, site));
  }

  xDonate(g, pct, target, site) {
    if (!(this.p.enableInflightLedger > 0)) return super.xDonate(g, pct, target, site);
    return this.ledgerSend(g, "donate", pct, target, site, (p) => super.xDonate(g, p, target, site));
  }

  xBoatTo(g, pct, land, radius, site) {
    if (this.p7BoatVeto(g, pct, land, site)) return false;
    if (!(this.p.enableInflightLedger > 0)) return super.xBoatTo(g, pct, land, radius, site);
    return this.ledgerSend(g, "boat", pct, land, site, (p) => super.xBoatTo(g, p, land, radius, site));
  }

  xBoat(g, pct, water, dir, site) {
    if (this.p7BoatVeto(g, pct, -1, site)) return false;
    if (!(this.p.enableInflightLedger > 0)) return super.xBoat(g, pct, water, dir, site);
    return this.ledgerSend(g, "boat", pct, water, site, (p) => super.xBoat(g, p, water, dir, site));
  }

  xRetreat(g, target, site) {
    if (!(this.p.enableInflightLedger > 0)) return super.xRetreat(g, target, site);
    return this.ledgerSend(g, "retreat", 0, target, site, () => super.xRetreat(g, target, site));
  }

  xChase(g, pct, id, site) {
    if (!(this.p.enableInflightLedger > 0)) return super.xChase(g, pct, id, site);
    return this.ledgerSend(g, "chase", pct, id, site, (p) => super.xChase(g, p, id, site));
  }

  xRecall(g, id, site) {
    if (!(this.p.enableInflightLedger > 0)) return super.xRecall(g, id, site);
    return this.ledgerSend(g, "recall", 0, id, site, () => super.xRecall(g, id, site));
  }

  isTurn(g) {
    const P = this.p;
    if (g.t % P.period === 0) {
      this.ledCarryN = 0;
      return true;
    }
    if (!(P.enableInflightLedger > 0 && P.p1CarryOver > 0) || this.ledCarryT !== g.t) return false;
    if (this.ledCarryAt !== g.t) {
      this.ledCarryAt = g.t;
      this.ledCarryN++;
      this.vCount("p1_carry_turn");
    }
    return true;
  }

  // (A command sends its share of the balance at the tick it lands, not of the balance it left
  // with: the troops are projected from today's balance, each command taking its share of what
  // the ones before it leave.)
  inflightOn(g, q) {
    if (!(this.p.enableInflightLedger > 0)) return 0;
    let s = 0, b = g.bal[this.me];
    for (const e of this.led) {
      if (!(e.share > 0)) continue;
      if (e.kind === "attack" && e.target === q) s += iV(b * (e.pct + 1), 1024);
      b *= 1 - e.share;
    }
    return s;
  }

  // Our balance once every command in flight has landed (each takes its share of what is left).
  ledProjected(g) {
    let b = g.bal[this.me];
    for (const e of this.led) if (e.share > 0) b *= 1 - e.share;
    return b;
  }

  // Guardrail 1: q has troops on us that our troops on it, landed or in flight, do not match.
  ledUrgent(g, q) {
    const me = this.me;
    if (q === NEUTRAL || q < 0 || !g.alive[q]) return false;
    const inc = g.attackTroopsOn(q, me);
    if (!(inc > 0) || inc < this.p.p1UrgentMin * g.bal[me]) return false;
    return g.attackTroopsOn(me, q) + this.inflightOn(g, q) < inc;
  }

  // Why a command may not leave now (null: it may).
  ledgerVeto(g, kind, pct, target) {
    const P = this.p, me = this.me, t = g.t;
    if (P.p1OneCmdPerTick > 0 && this.ledLastCmdT === t) {
      if (P.p1CarryOver > 0 && this.ledCarryN < P.p1CarryMax) this.ledCarryT = t + 1;
      return "tick";
    }
    if (!(FEE_OF[kind] > 0)) return null;
    const urgent = kind === "attack" && P.p1CounterExempt > 0 && this.ledUrgent(g, target);
    if (urgent) return null;
    let recent = 0;
    for (let i = this.ledSent.length - 1; i >= 0 && t - this.ledSent[i] < 21; i--) recent++;
    if (recent >= P.p1RoundCap) return "cap";
    if (this.ledStall) {
      if (kind === "donate") return "stall_donate";
      if (kind === "boat") return "stall_boat";
      if (target !== NEUTRAL) {
        for (const e of this.led) if (e.kind === "attack" && e.target === target && !e.weak) return "stall_same";
        if (target >= 0 && this.person(g, target) && !this.vShell(g, target)) return "stall_person";
      }
      if (Math.floor(t / 7) === this.ledRound) return "stall_round";
    }
    const B = g.bal[me], proj = this.ledProjected(g);
    if (proj < B) {
      const keep = this.vKeepNext;
      if (keep === null || keep === undefined) {
        if (proj < P.p1ProjFrac * B) return "proj";
      } else if (proj * (1 - (pct + 1 + FEE_OF[kind]) / 1024) < keep) return "keep";
    }
    return null;
  }

  ledgerSend(g, kind, pct, target, site, fn) {
    const P = this.p, me = this.me;
    const bal0 = g.bal[me];
    let scaled = false;
    // A command takes its share of the balance of the tick it lands, after the commands in flight
    // have taken theirs: the share is raised so that what lands is what the caller sized on
    // today's balance (pct 0 is the one-ring probe and stays).
    if (P.p1ScaleUp > 0 && FEE_OF[kind] > 0 && pct > 0 && this.led.length) {
      const proj = this.ledProjected(g);
      if (proj > 0 && proj < bal0) {
        const p2 = Math.min(1023, Math.ceil(((pct + 1) * Math.min(P.p1ScaleMax, bal0 / proj))) - 1);
        if (p2 > pct) {
          pct = p2;
          scaled = true;
        }
      }
    }
    const why = this.ledgerVeto(g, kind, pct, target);
    this.vKeepNext = null;
    if (why) {
      this.vCount("p1_veto_" + why);
      return false;
    }
    const ok = fn(pct);
    if (!ok) {
      this.vCount("p1_host_refused");
      return false;
    }
    const t = g.t, fee = FEE_OF[kind] ?? 0;
    this.ledLastCmdT = t;
    this.ledSent.push(t);
    if (this.ledSent.length > 32) this.ledSent.splice(0, this.ledSent.length - 32);
    if (this.ledStall && kind === "attack") this.ledRound = Math.floor(t / 7);
    this.vCount("p1_issue_" + kind);
    if (scaled) this.vCount("p1_scale_up");
    // a host that executes at once has made us pay by now: nothing is in flight
    const paid = fee > 0 ? g.bal[me] <= bal0 - iV(fee * bal0, 1024) && g.bal[me] < bal0 : kind === "retreat" && !g.hasAttack(me, target);
    if (paid) {
      this.vCount("p1_sync");
      return true;
    }
    const exp = fee > 0 ? Math.max(0, Math.min(iV(bal0 * (pct + 1), 1024), bal0 - iV(fee * bal0, 1024))) : 0;
    this.led.push({ id: ++this.ledSeq, t, kind, target, pct, share: fee > 0 ? Math.min(1, (pct + 1 + fee) / 1024) : 0, exp, site, weak: !(fee > 0) || pct === 0 });
    if (kind === "attack" && !this.ledAtkSeen.has(target)) this.ledAtkSeen.set(target, g.attackTroopsOn(me, target));
    if (this.p.v28Debug > 0) this.vLog("LED", g, `issue #${this.ledSeq} ${kind} q=${target} pct=${pct} exp=${exp} site=${site} bal=${bal0} inflight=${this.led.length}`);
    return true;
  }

  // Forget every command in flight (for a host that takes the seat over mid-game, or a bridge that
  // reconnects: what was in flight before is not ours to wait for).
  ledgerReset() {
    this.led.length = 0;
    this.ledAtkSeen.clear();
    this.ledPrev = null;
    this.ledStall = false;
    this.ledCarryT = -1;
    this.ledLandedT = -1;
    this.ledSlots = null;
  }

  // Whether the game would refuse attack e if it arrived now: no attack of ours on its target to
  // add to and, as of our last look at the border (analyze), no border with it.
  ledNoFront(g, e) {
    if (g.hasAttack(this.me, e.target)) return false;
    return e.target === NEUTRAL ? !(this.neutral > 0) : !(this.cnt[e.target] > 0);
  }

  ledClose(g, e, how) {
    const i = this.led.indexOf(e);
    if (i >= 0) this.led.splice(i, 1);
    this.vCount(`p1_${how}_${e.kind}`);
    if (this.p.v28Debug > 0) this.vLog("LED", g, `close #${e.id} ${how} ${e.kind} q=${e.target} age=${g.t - e.t} bal=${g.bal[this.me]}`);
    if (how === "land" || how === "step") {
      if (e.t > this.ledLandedT) this.ledLandedT = e.t;
      const lat = g.t - e.t;
      this.vCount("p1_lat_sum", lat);
      this.vCount("p1_lat_n");
      if (lat > (this.v28n.p1_lat_max || 0)) this.v28n.p1_lat_max = lat;
    }
  }

  // Wall clock against ticks (live only): a long gap between two ticks (the page stood still) or
  // ticks arriving in a burst (the bridge replaying what it missed) both mean that what we read is
  // old and what we send is late.
  ledClock(g) {
    const P = this.p, t = g.t;
    if (!g.online) return;
    const now = this.vNow();
    if (this.ledClockT >= 0 && t > this.ledClockT) {
      const dMs = now - this.ledClockMs, dT = t - this.ledClockT;
      if (dMs > P.p1StallMs) this.ledClockStallUntil = t + 21;
      this.ledBurstTicks = dMs / dT < P.p1BurstMs ? this.ledBurstTicks + dT : 0;
      if (this.ledBurstTicks >= P.p1BurstTicks) this.ledClockStallUntil = t + 14;
    }
    this.ledClockT = t;
    this.ledClockMs = now;
  }

  // Every tick: which commands in flight have landed (event driven: a boat of ours more at sea, our
  // troops on a target up, a step down in our balance of the right size), which have no target left,
  // which are lost; then whether the channel stalls.
  ledgerObserve(g) {
    const P = this.p, me = this.me, t = g.t, B = g.bal[me];
    const boats = g.boatCount ? g.boatCount[me] : 0;
    const prev = this.ledPrev;
    this.ledPrev = { t, bal: B, boats };
    this.ledClock(g);

    const flag = "noFullSend" in g ? Boolean(g.noFullSend) : null;
    if (P.p1NoFullFix > 0 && flag !== null) this.isNoFullSend = flag || Boolean(P.noFullSend);

    if (this.led.length && prev) {
      let landed = 0, landedAtk = null, donLanded = false;
      const done = [];
      const close = (e, how) => {
        landed++;
        if (e.kind === "attack") landedAtk = e;
        if (e.kind === "donate") donLanded = true;
        if (e.share > 0) done.push(e);
        this.ledClose(g, e, how);
      };
      // 1. what certainly landed: one boat per boat of ours more at sea, and the oldest command on
      // every target our troops on which went up
      for (let k = boats - prev.boats; k > 0; k--) {
        const e = this.led.find((x) => x.kind === "boat");
        if (!e) break;
        close(e, "land");
      }
      const risen = [];
      for (const [q, seen] of this.ledAtkSeen) {
        const cur = g.attackTroopsOn(me, q);
        this.ledAtkSeen.set(q, cur);
        let rise = cur - seen;
        // (troops the game moved onto free land because their target is gone are no landing)
        if (q === NEUTRAL && rise > 0 && this.ledSlots) {
          for (const [o, tr] of this.ledSlots) if (o !== NEUTRAL && (!g.alive[o] || !g.terr[o]) && !g.hasAttack(me, o)) rise -= tr;
        }
        if (!(rise > 0)) continue;
        const e = this.led.find((x) => x.kind === "attack" && x.target === q);
        if (!e) continue;
        close(e, "land");
        risen.push({ q, rise, first: e });
      }
      // 2. whether the next command on such a target landed with it. A command sends its share of
      // the balance of the tick it lands; of the commands of one tick the one that left last lands
      // first. Undoing them from today's balance, oldest first, gives what each landed with (b:
      // the balance before them); the next one counts as landed when the rise that the first
      // does not explain is at least p1AlsoK of what it would have landed with.
      let b = B;
      done.sort((x, y) => x.id - y.id);
      for (const e of done) {
        b /= Math.max(1 - e.share, 0.02);
        e.got = iV(b * (e.pct + 1), 1024);
      }
      for (const r of risen) {
        let rem = r.rise - r.first.got;
        for (;;) {
          const next = this.led.find((x) => x.kind === "attack" && x.target === r.q);
          if (!next) break;
          const before = b / Math.max(1 - next.share, 0.02);
          const got = iV(before * (next.pct + 1), 1024);
          if (rem < P.p1AlsoK * got) break;
          close(next, "land");
          b = before;
          rem -= got;
        }
      }
      for (const e of [...this.led]) {
        if (e.kind === "retreat" && !g.hasAttack(me, e.target)) this.ledClose(g, e, "land");
      }
      if (t - prev.t === 1) {
        // 3. a tick in which nothing was seen landing: a drop in our balance of the size of the
        // oldest command it matches is that command (landed and spent within the tick, or a donation)
        if (landed === 0) {
          let rest = prev.bal - B;
          for (const e of [...this.led]) {
            if (!(e.share > 0) || e.weak || t - e.t < P.p1MinLat) continue;
            const cost = prev.bal * e.share;
            if (rest >= P.p1StepLo * cost && rest <= P.p1StepHi * cost) {
              close(e, "step");
              rest -= cost;
            }
          }
        }
        // isNoFullSend probe: exactly one attack landed this tick, no donation of ours with it, no
        // interest in between (interest and rent come on ticks 9 of 10; one tick of slack either side)
        const ph = prev.t % 10;
        if (P.p1NoFullFix > 0 && flag === null && landed === 1 && landedAtk && !landedAtk.weak && !donLanded && ph !== 8 && ph !== 9 && ph !== 0) {
          const fee = iV(12 * prev.bal, 1024);
          const sent = Math.max(0, prev.bal - B - fee);
          const want = iV(prev.bal * (landedAtk.pct + 1), 1024);
          if (want >= 1.12 * sent && sent < prev.bal - fee - 50) {
            this.vCount("p1_nfs_trunc");
            if (++this.nfsTrunc >= P.p1NoFullM && !this.isNoFullSend) {
              this.isNoFullSend = true;
              this.nfsByProbe = true;
              this.shadowQuota = 0;
              this.vCount("p1_nfs_set");
              this.vLog("NFS", g, `set after ${this.nfsTrunc} truncated landings (want=${want} sent=${sent})`);
            }
          } else {
            this.nfsTrunc = 0;
            this.shadowQuota = Math.max(0, this.shadowQuota - sent);
            if (this.nfsByProbe && this.isNoFullSend) {
              this.isNoFullSend = Boolean(P.noFullSend);
              this.nfsByProbe = false;
              this.vCount("p1_nfs_reset");
              this.vLog("NFS", g, `reset by a full landing (want=${want} sent=${sent})`);
            }
          }
        }
      }
    }

    // Commands that will not land as they left. `soft` entries are those the game is likely to
    // refuse on arrival (a refused command costs nothing and shows nowhere): they stay counted as
    // in flight for the normal window and are no evidence of a stall.
    for (const e of [...this.led]) {
      const age = t - e.t;
      if (e.kind === "attack" && e.target !== NEUTRAL && !g.alive[e.target]) {
        // the game turns an attack on a player that is gone into one on free land
        e.target = NEUTRAL;
        e.soft = true;
        if (!this.ledAtkSeen.has(NEUTRAL)) this.ledAtkSeen.set(NEUTRAL, g.attackTroopsOn(me, NEUTRAL));
        this.vCount("p1_retarget");
      }
      if (e.kind === "attack" && !e.soft && !e.weak && this.ledNoFront(g, e)) {
        e.soft = true;
        this.vCount("p1_soft");
      }
      if (e.weak ? age > P.p1NormalWin : e.soft ? age > P.p1StallAfter : age > P.p1DropAfter) {
        this.ledClose(g, e, e.weak ? "weak" : e.soft ? "soft" : "drop");
      } else if (!e.weak && age > P.p1NormalWin && this.ledLandedT >= e.t + 7) {
        // a command that left a settlement round later has landed: this one was refused or dropped
        this.ledClose(g, e, "lost");
      }
    }
    for (const q of [...this.ledAtkSeen.keys()]) {
      if (!this.led.some((e) => e.kind === "attack" && e.target === q)) this.ledAtkSeen.delete(q);
    }
    // our attacks as they stand, for the next tick (only while something is in flight)
    if (this.led.length) {
      const m = (this.ledSlots ??= new Map());
      m.clear();
      const base = g.slotBase(me);
      for (let i = g.atkCount[me] - 1; i >= 0; i--) m.set(g.atkTarget[base + i], g.atkTroops[base + i]);
    } else this.ledSlots = null;

    let why = "";
    for (const e of this.led) {
      if (!e.weak && !e.soft && t - e.t > P.p1StallAfter) {
        why = "late";
        break;
      }
    }
    if (!why && t < this.ledClockStallUntil) why = "clock";
    if (why && !this.ledStall) {
      this.ledStall = true;
      this.vCount("p1_stall_enter");
      this.vLog("STALL", g, `enter why=${why} inflight=${this.led.length} oldest=${this.led.length ? t - this.led[0].t : 0}`);
    } else if (!why && this.ledStall) {
      this.ledStall = false;
      this.vLog("STALL", g, "leave");
    }
    if (this.ledStall) this.vCount("p1_stall_tick");
  }
}

